class Solution {
public:
    int findLengthOfShortestSubarray(vector<int>& arr) {

        int n =(int) arr.size();
        int h = n-1, l=0;

        for(int i=h;i>=1;i--)  
        {
            if(arr[i]>=arr[i-1] && h>0)
            {
                h--; break;
            }
            else break;
        }

        int res=h;

        for(l=0 ; l<h && (l==0 || arr[l-1]<=arr[l]); l++)
        {
            while(h<n && arr[l]>arr[h])
            {
                h++;
            }

            res = min(res,h-l-1);
       }
       return res;
    }
};

class Solution {
public:
    int beautifulSubsets(vector<int>& nums, int k) {
        vector<int> cur;
        return helper(nums, k, cur, 0);
    }
    private:
    int helper(vector<int>& nums, int k, vector<int>& cur, int start) {
        int cnt = 0;
        for (int i = start; i < nums.size(); ++i) {
            if (!test(cur, nums[i], k))
                continue
            cur.push_back(nums[i]);
            cnt++;
            cnt += helper(nums, k, cur, i + 1);
            cur.pop_back();
        }
        return cnt;
    }
    bool test(vector<int>& cur, int num, int k) {
        for (auto &c : cur)
            if (abs(num - c) == k)
                return false;
        return true;
    }
};

