class Solution {
public:
    vector<int> filterRestaurants(vector<vector<int>>& restaurants, int veganFriendly, int maxPrice, int maxDistance) {
        if(veganFriendly == 1){
            for(int i = 0; i<restaurants.size(); i++){
                if(restaurants[i][2] != veganFriendly){
                    restaurants[i][0] = -1;
                }
            }
        }

        for(int i = 0; i<restaurants.size(); i++){
            if(restaurants[i][3] > maxPrice){   
                restaurants[i][0] = -1;
            }
            if(restaurants[i][4] > maxDistance){  
                restaurants[i][0]=-1;
            }
        }

        vector<int> id;
        vector<int>rating;
        for(int i=0; i<restaurants.size(); i++){
            if(restaurants[i][0]>0){
                id.push_back(restaurants[i][0]);
                rating.push_back(restaurants[i][1]);
            }

        }

        for(int i=0; i<rating.size(); i++){
            for(int j=i+1; j<rating.size(); j++){
                if(rating[i] < rating[j]){
                    swap(rating[i], rating[j]);
                    swap(id[i], id[j]);
                }
            }
        }

        for(int i=0; i<rating.size(); i++){
            for(int j=i+1; j<rating.size(); j++){
                if(rating[i] == rating[j] && id[i] < id[j]){
                    swap(id[i], id[j]);
                }
            }
        }

        return id;
    }
};

class Solution {
public:
    int longestValidSubstring(string word, vector<string>& forbidden) {
        vector<int> ends(word.size() , -1);
        unordered_map<string, int> forbidden_word;
        for(auto it : forbidden)forbidden_word[it] = 1;
        int n = word.size();
        for(int i = 0; i<n; i++){
            string temp = "";
            for(int j = i; j<i+10 && j<n; j++){
                temp += word[j];
                if(forbidden_word.find(temp) != forbidden_word.end()) {
                    ends[j] = i;
                }
            }
        }

        int i = 0, j = 0;
        int ans = INT_MIN;
        while(j < n){

            if(ends[j] != -1){
                int st = ends[j];
                if(st < i){
                    ans = max(ans, j-i+1);
                }
                else{
                    i = st+1;
                    ans = max(ans, j-i+1);
                }
            }
            else ans = max(ans,j-i+1);
            j++;
        }
        return ans;
    }
};

class Solution {
public:
    int myAtoi(string s) {
        long long res = 0; // stores our integer value
        bool neg = 0; // checks whether integer will be -ve or +ve
        bool leading = true; // true if theres leading spaces 

        int n = s.size();

        for (int i = 0; i<n; i++) {
            if (s[i] == ' ') { // checks for leading spaces
                if (leading) continue;
                else break;
            }
            else if (s[i] == '-') { // checks -ve 
                if (i+1 < n && isdigit(s[i+1])) neg = 1;
                else break; // break if next char is non-digit
            }
            else if (s[i] == '+') { // checks for +ve
                if (i+1 < n && isdigit(s[i+1])) neg = 0;
                else break; // break if next char is non-digit
            }
            else if (!isdigit(s[i])) break; // break on encoutring non-digit
            else { // storing our integer value to res
                if (res < 1e11) {
                    res = res*10 + (s[i]-'0');
                    if (i+1 < n && !isdigit(s[i+1])) 
                        break;// break if next char is non-digit
                }
                else break;
                leading = false; // tells that integer has been encoutered
            }
        }

        if (res > INT_MAX && neg) return INT_MIN;
        if (res > INT_MAX) return INT_MAX;

        return neg ? -1*res : res;
    }
};

class Solution {
public:
    int rec(int ind,string &s,set<string>&st,vector<int>&dp)
    {
        if (ind==s.size()) return 0;
        if (dp[ind]!=-1) return dp[ind];
        int ans=s.size()-ind;
        for (int i=ind;i<s.size();i++)
        {
           string temp=s.substr(ind,i-ind+1);
           if (st.find(temp)!=st.end())
              ans=min(ans,rec(i+1,s,st,dp));
           }

        ans=min(ans,1+rec(ind+1,s,st,dp))
        return dp[ind]=ans;
    }
    int minExtraChar(string s, vector<string>& dictionary) 
    {
        set<string>st;
        int n=s.size();
        vector<int>dp(n,-1);
        for (auto it:dictionary)
        {
            st.insert(it);
        }
        return rec(0,s,st,dp);
    }
};

class Solution {
public:
    vector<vector<string>> groupAnagrams(vector<string>& strs) {
        unordered_map<string,int> m;
        vector<vector<string>> ans;
        for(int i=0; i<strs.size(); i++) 
            string str = strs[i];
            sort(str.begin(),str.end());

            if(m.find(str) != m.end()) {
                ans[m[str]].push_back(strs[i]);
            }
            else {
                m[str] = ans.size(); 
                ans.push_back({strs[i]});
            }
        }
        return ans;
    }
