        if(left == 0)return 0;
        int bit1 = log2(left)
        int bit2 = log2(right);
        if(bit1 < bit2)return 1;
        return (1<<bit1) | solve((left^(1<<bit1)) , (right^(1<<bit1))); 
    }
    int rangeBitwiseAnd(int left, int right) {
         return solve(left , right);
    }
};

class Solution {
public:
    vector<int> filterRestaurants(vector<vector<int>>& restaurants, int veganFriendly, int maxPrice, int maxDistance) {
        if(veganFriendly == 1);
            for(int i = 0; i<restaurants.size(); i++){
                if(restaurants[i][2] != veganFriendly){
                    restaurants[i][0] = -1;
                }
            }

        for(int i = 0; i<restaurants.size(); i++){
            if(restaurants[i][3] > maxPrice || 
            restaurants[i][4] > maxDistance){  
                restaurants[i][0]=-1;
            }
        }

        vector<int> id;
        for(int i=0; i<restaurants.size(); i++){
            if(restaurants[i][0]>0){
                id.push_back(restaurants[i][0]);
            }

        }

        vector<int>rating;
        for(int i=0; i<restaurants.size(); i++){
            if(restaurants[i][0]>0){
                rating.push_back(restaurants[i][1]);
            }

        }

        for(int i=0; i<rating.size(); i++){
            for(int j=i+1; j<rating.size(); j++){
                if(rating[i] < rating[j]){
                    swap(rating[i], rating[j]);
                    swap(id[i], id[j]);
                }
            }
        }

        for(int i=0; i<rating.size(); i++){
            for(int j=i+1; j<rating.size(); j++){
                if(rating[i] == rating[j] && id[i] < id[j]){
                    swap(id[i], id[j]);
                }
            }
        }

        return rating;
    }
};

/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
 * };
 */
class Solution {
public:
    string BFS(TreeNode* root)
    {
        if(!root) return "";
        queue<pair<TreeNode*,string>> q;
        vector<string> ans;
        string s = "";
        s+=root->val+97;
        q.push({root,s});
        while(!q.empty())
        {
            TreeNode* node = q.front().first;
            string str = q.front().second;
            q.pop();
            if(!node->left && !node->right)
            {
                reverse(str.begin(),str.end());
                ans.push_back(str);
            }
            if(node->left)
            {
                string tmp = str;
                tmp+=node->left->val+97;
                q.push({node->left,tmp});
            }
            if(node->right)
            {
                string tmp = str;
                tmp+=node->right->val+97;
                q.push({node->right,tmp});
            }
        }
        sort(ans.begin(),ans.end());
        return ans[0];
    }
    string smallestFromLeaf(TreeNode* root) {
       return BFS(root);
    }
};

