class LRUCache {
public:
class node
{
  public:
  int key;
  int val;
  node* next;
  node* prev;
  node(int _key,int _val)
  {
    key = _key;
    val = _val;
  }
};
node* head = new node(-1,-1);
node* tail = new node(-1,-1);

int size;
unordered_map<int,node*>mpp;
    LRUCache(int capacity) {
       size = capacity; 
       head->next = tail;
       tail->prev = head;  
    }

    void addNode(node* newNode){

       node* temp = head->next;
       newNode->next = temp;
       newNode->prev = head;
       head->next = newNode;
       temp->prev = newNode;
    }

    void deleteNode(node* delNode){

       node* delprev = delNode->prev;
       node* delnext = delNode->next;
       delprev->next = delnext;
       delnext->prev = delprev;
    }

    int get(int _key) {

        if(mpp.count(_key))
        {
          node* nde = mpp[_key];
          int curr = nde->val;
          mpp.erase(_key);
          deleteNode(nde);
          addNode(nde);
          mpp[_key] = head->next;
          return curr;
        }
        return -1;
    }

    void put(int _key, int value) {

        if(mpp.count(_key))
        {
           node* nde = mpp[_key];
           mpp.erase(_key);
           deleteNode(nde);
        }
        if(mpp.size()==size)
        {
           mpp.erase(tail->prev->key);
           deleteNode(tail->prev);
        }
        addNode(new node(_key,value));
        mpp[_key] = head->next;
    }
};

class Solution {
public:
    #define mod 1000000007
    long long dp[102][10][2][2];
    long long f(string &r,int n,int pre,int leadingZero,int tight){
        if(n==0) return 1;

        if(dp[n][pre][leadingZero][tight]!=-1) return dp[n][pre][leadingZero][tight];
        long long up = tight ? (r[r.size()-n]-'0'):9,ans=0;

        if(leadingZero){
            for(int i=0;i<=up;i++){
                ans = (ans + f(r,n-1,i,(i==0),tight&(i==up)))%mod; 
            }
        } else {
            if(pre-1>=0 && pre-1<=up) ans = (ans + f(r,n-1,pre-1,0,tight&(pre-1==up)))%mod;
            if(pre+1<=up) ans = (ans + f(r,n-1,pre+1,0,tight&(pre+1==up)))%mod;
        }


        return dp[n][pre][leadingZero][tight]=ans;
    }
    int countSteppingNumbers(string low, string high) {
        int n=high.size();
        memset(dp,-1,sizeof(dp));
        long long r= f(high,high.size(),0,1,1);
        memset(dp,-1,sizeof(dp));
        for(int i=low.size()-1;i>=0;i--){
            if((low[i]-'0')>0){
                low[i]--;break;
            } else {
                low[i]='9';
            }
        }

        // cout<<low<<endl;
        long long l= f(low,low.size(),0,1,1);
        cout<<l<<" "<<r<<endl;
        return (r-l+mod)%mod;
    }
};

