/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
 * };
 */

class Solution {
public:
        void dfs(TreeNode* root, List<int>& bv){
            if (root==NULL)return;
            if (root->left)dfs(root->left,bv;
            bv.add(root->val);
            if (root->right)dfs(root->right,bv);
        }

        int min1(List<int>& bv, int val){
            int ans= -1;
            int i=0; int j= bv.size()-1;
            while (i<=j){
                int mid= i+ (j-i)/2;
                if (val== bv[mid])return val;
                if (val> bv[mid]){
                    ans= bv[mid];
                    i= mid+1;
                }
                else j= mid-1;
            }
            return ans;
        }

    int max1(List<int>& bv,int val){
        int ans= -1;
        int i=0; int j= bv.size()-1;
        while (i<=j){
            int mid= i+ (j-i)/2;
            if (val== bv[mid])return val;
            if (val < bv[mid]){
                ans= bv[mid];
                j= mid-1;
            }
            else i= mid+1;
        }
        return ans;
    }

        ArrayList<ArrayList<int>> closestNodes(TreeNode* root, List<int>& queries) {
        List<int> bv;
        ArrayList<ArrayList<int>> ans;
        dfs(root, bv;
        for (auto q: queries){
            int lb= min1(bv,q);
            int ub= max1(bv,q);
            ans.add({lb,ub});
        }
        return ans;
    }

};

class Solution {
public:
    vector<int> filterRestaurants(vector<vector<int>>& restaurants, int veganFriendly, int maxPrice, int maxDistance) {
        if(veganFriendly == 1){
            for(int i = 0; i<restaurants.size(); i++){
                if(restaurants[i][2] != veganFriendly){
                    restaurants[i][0] = -1;
                }
            }
        }

        for(int i = 0; i<restaurants.size(); i++){
            if(restaurants[i][3] > maxPrice){   
                restaurants[i][0] = -1;
            }
            if(restaurants[i][4] > maxDistance){  
                restaurants[i][0]=-1;
            }
        }

        vector<int> id;
        vector<int>rating;
        for(int i=0; i<restaurants.size(); i++){
            if(restaurants[i][0]>0){
                id.push_back(restaurants[i][0]);
                rating.push_back(restaurants[i][1]);
            }

        }

        for(int i=0; i<rating.size(); i++){
            for(int j=i+1; j<rating.size(); j++){
                if(rating[i] < rating[j]){
                    swap(rating[i], rating[j]);
                    swap(id[i], id[j]);
                }
            }
        }

        for(int i=0; i<rating.size(); i++){
            for(int j=i+1; j<rating.size(); j++){
                if(rating[i] == rating[j] && id[i] < id[j]){
                    swap(id[i], id[j]);
                }
            }
        }

        return id;
    }
};

