class Solution {
public:
    int shortestPathLength(vector<vector<int>>& graph) {
        int n=graph.size();
        if(n==1) return 0;
        set<pair<int,int>>vis;
        queue<pair<int,pair<int,int>>>q;
        int all=(1<<n)-1;
        for(int i=0;i<n;i++){
            int mask=1<<i;
            q.push({i,{0,mask}});
            vis.insert({i,mask});
        }
        while(!q.empty()){
            int node=q.front().first;
            int dist=q.front().second.first;
            int mask=q.front().second.second;
            q.pop();
            for(auto it:graph[node]){
                int newMask=(mask|(1<<it));
                if(newMask==all)
                    return dist+1;
                else if(vis.count({it,newMask}))
                    continue;
                q.push({it,{dist+1,newMask}});
                vis.insert({it,newMask});
            }
        }
        return 0;
    }
};

class Solution {
public:
    int longestValidSubstring(string word, vector<string>& forbidden) {
        vector<int> ends(word.size() , -1);
        unordered_map<string, int> forbidden_word;
        for(auto it : forbidden) forbidden_word[it] = 1;
        int n = word.size();
        for(int i = 0; i<n; i++){
            string temp = "";
            for(int j = i; j<i+10 && j<n; j++){
                temp += word[j];
                if(forbidden_word.find(temp) != forbidden_word.end()) {
                    ends[j] = i;
                }
            }
        }

        int i = 0, j = 0;
        int ans = INT_MIN;
        while(j < n){

            if(ends[j] != -1){
                int st = ends[j];
                if(st < i){
                    ans = max(ans, j-i+1);
                }
                else{
                    i = st+1;
                    ans = max(ans, j-i);
                }
            }
            else ans = max(ans,j-i+1);
                j++;
                j++;
        }
        return longestSubsequence(ans, ends);
    }

};

