            if(check(nums[i][i]) && nums[i][i]>ans){
                ans = nums[i][i];
            }
            if(check(nums[i][n-i]) && nums[i][n-i]>ans){
                ans = nums[i][n-i];
            }
        }
        return ans;
    }
};

