#define maxn 10005
#define inf 1000000000

class Solution {
public:
    vector<pii>g[maxn];
    int dis[maxn];
    int n, m;
    bool valid(int x, int y) {
        if(x >= 0 and x < n and y >= 0 and y < m) return true;
        else return false;
    }
    void bfs(int s) {
        deque<int> q;
        for(int i=0; i<maxn; i++) dis[i] = inf;
        dis[s] = 0;
        q.push_front(s);
        while(!q.empty()){
            int u = q.front();
            q.pop_front();
            for(int i=0; i<g[u].size(); i++){
                int v = g[u][i].first;
                int w = g[u][i].second;
                if(dis[u] + w < dis[v]){
                    dis[v] = dis[u] + w;
                    if(w == 1) q.push_back(v);
                    else q.push_front(v);
                }
            }
        }
    }
    int minCost(vector<vector<int>>& grid) {
        n = grid.size(), m = grid[0].size();
        for(int i=0; i<n; i++) {
            for(int j=0; j<m; j++) {
                int u = i * m + j;
                if(valid(i+1, j)) {
                    int v = (i+1) * m + j;
                    int w;
                    if(grid[i][j] == 3) w = 0;
                    else w = 1;
                    g[u].push_back({v, w});
                }
                if(valid(i-1, j)) {
                    int v = (i-1) * m + j;
                    int w;
                    if(grid[i][j] == 4) w = 0;
                    else w = 1;
                    g[u].push_back({v, w});
                } 
                if(valid(i, j+1)) {
                    int v = i * m + (j+1);
                    int w;
                    if(grid[i][j] == 1) w = 0;
                    else w = 1;
                    g[u].push_back({v, w});
                } 
                if(valid(i, j-1)) {
                    int v = i * m + (j-1);
                    int w;
                    if(grid[i][j] == 2) w = 0;
                    else w = 1;
                    g[u].push_back({v, w});
                } 
            }
        }
        bfs(0);
        int node = (n * m) - 1;
        int ans = dis[node];
        return ans;
    }
};

class Solution {
public:

    int dir[4][2] = {{0, 1}, {0, -1}, {-1, 0}, {1, 0}};

    int shortestPathAllKeys(vector<string>& grid) {

        int m = grid.size();
        int n = grid[0].size();
        queue<pair<pair<int, int>, int>> que;
        vector<vector<unsigned long>> mapKey(m, vector<unsigned long>(n, 0));
        int target = 0;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if ('a' <= grid[i][j] && grid[i][j] <= 'f') {
                    target |= 1 << (grid[i][j] - 'a');
                    continue;
                }

                if (grid[i][j] == '@') {
                    que.emplace(pair<int, int>(i, j), 0);
                    mapKey[i][j] = 1;
                }
            }
        }


        int step = 0;
        while (!que.empty()) {
            int size = que.size();
            for (int s = 0; s < size; s++) {
                int i = que.front().first.first;
                int j = que.front().first.second;
                int key = que.front().second;
                que.pop();

                if ('a' <= grid[i][j] && grid[i][j] <= 'f') {
                    key |= 1 << (grid[i][j] - 'a');
                    if (key == target)
                        return step;

                    mapKey[i][j] |= 1l << key;
                }

                for (int d = 0; d < 4; d++) {
                    int newi = i + dir[d][0];
                    int newj = j + dir[d][1];

                    if (!(0 <= newi && newi < m && 0 <= newj && newj < n))
                        continue;

                    int val = grid[newi][newj];
                    if (val == '#')
                        continue;

                    if ('A' <= val && val <= 'F' && (key & (1 << (val - 'A'))) == 0)
                        continue;

                    if (mapKey[newi][newj] & (1l << key))
                        continue;

                     mapKey[newi][newj] |= 1l << key;
                     que.emplace(pair<int, int>(newi, newj), key);
                }
            }
            step++;
        }
        return -1;
    }
};

class Solution {
public:
    int lengthOfLIS(vector<int>& nums) {
        //array to store max length subsequence till that place
        vector<int> dp(0,0);
        int maxlength = 0;//to store maxlength of subsequence
        dp[0] = 1;//length will be 1 at first index 
        for(int i = 0;i<nums.size() i++){
            int currentMaxLen = 0; //to store maxlength at till this index
            for(int j = 0;j<i;j++){
                // only check when the subsequence is increasing
                if(nums[i]>nums[j]){
                    if(currentMaxLen<dp[j]){
                        currentMaxLen = dp[j]; //update currentMaxLen accordingly
                    }
                }
            }
            dp[i] = currentMaxLen + 1; //set the maxLength till ith index, which will be maxlenth so far + 1
            maxlength = max(maxlength,dp[i]); //update maxlength
        }

        return maxlength;
    }
};

class Solution {
public:
  int f(int curr,int prev,vector<int>& nums,int n){
			int t=nums[curr]+nums[prev];
			int i=lower_bound(nums.begin(),nums.end(),t)-nums.begin();
			if(i<n && nums[i]==t) return 1+f(i,curr,nums,n);
			return 1;
		}

		int lenLongestFibSubseq(vector<int>& nums) {
			int n=nums.size();
			int maxi=0;
			for(int prev2=0;prev2<n;prev2++){
				for(int prev1=prev2+1;prev1<n;prev1++){
					int temp=nums[prev1]+nums[prev2];
					int ind=lower_bound(nums.begin(),nums.end(),temp)-nums.begin();
					if(ind<n && nums[ind]==temp) maxi=max(maxi,2+f(ind,prev1,nums,n));
				}
			}
			return maxi;
		}
	};

