class Solution {
public:
    // Global Vector to all possible column combinations
    vector<vector<int>>comb;

    // Function to find the number of rows a particular column combination can capture
    int find(vector<vector<int>>& mat1)
    {
        int c = 0;
        for(int i = 0; i < mat1.size(); i++)
        {
            int flg = 0;
            for(int j = 0; j < mat1[0].size(); j++)
                if(mat1[i][j] == 1)
                    flg = 1;
            if(flg == 0)
                c++;
        }
        return c;
    }

	// Function to Traverse for each Column Combination Present
    int find_ans(vector<vector<int>>& mat)
    {
        int ans = 0;
        for(int i = 0; i < comb.size(); i++)
        {
            vector<int>temp = comb[i];
            vector<vector<int>> mat1 = mat;
            for(int j = 0; j < temp.size(); j++)
            {
                int col_val = temp[j];
                for(int k = 0; k < mat1.size(); k++)
                    mat1[k][col_val] = 0;
            }
            ans = max(ans, find(mat1));
        }
        return ans;
    }
    // Function to Find all possible column combinations
    void helper(vector<vector<int>>& mat, int cols, int count, int idx, vector<int>tans)
    {
        int col = mat[0].size();
        if(count == cols)
        {
            comb.push_back(tans);
            return;
        }
        if(idx >= col)
            return;

        helper(mat, cols, count, idx+1, tans);
        tans.push_back(idx);
        helper(mat, cols, count+1, idx+1, tans);
    }

    int maximumRows(vector<vector<int>>& mat, int cols) {

        vector<int>tans;
        helper(mat, cols, 0, 0, tans);
        return find_ans(mat);
    }
};

class Solution {
public:
    int dp[9][9][9][9][140];
    int dx[4] = {0,1,0,-1};
    int dy[4] = {1,0,-1,0};

    bool solve(vector<string>& grid, int catJump, int mouseJump, int catR, int catC, int mouseR, int mouseC, int moves){        
        int r = grid.size(), c = grid[0].size();
        if(moves >= 128) return false;
        if(mouseR==catR && mouseC==catC) return false;
        if(grid[mouseR][mouseC] == 'F') return true;

        if(dp[catR][catC][mouseR][mouseC][moves] != -1) 
            return dp[catR][catC][mouseR][mouseC][moves];

        if(moves%2 == 0){
            for(int i=0; i<4; ++i){
                for(int j=0; j<=mouseJump; ++j){
                    int x = mouseR+j*dx[i], y = mouseC+j*dy[i];
                    if(x>=0 && x<r && y>=0 && y<c && grid[x][y]!='#'){
                        if(solve(grid, catJump, mouseJump, catR, catC, x, y, moves+1) == true) 
                            return dp[catR][catC][mouseR][mouseC][moves] = true;
                    }else break;
                }
            }
            return dp[catR][catC][mouseR][mouseC][moves] = false;
        }else{
            for(int i=0; i<4; ++i){
                for(int j=0; j<=mouseJump; ++j){
                    int x = catR+dx[i]*j, y = catC+dy[i]*j;
                    if(x>=0 && x<r && y>=0 && y<c && grid[x][y]!='#'){
                        if(solve(grid, catJump, mouseJump, x, y, mouseR, mouseC, moves+1) == false) 
                            return dp[catR][catC][mouseR][mouseC][moves] = false; 
                    }else break;
                }
            }
            return dp[catR][catC][mouseR][mouseC][moves] = true;
        }
        if(grid[catR][catC] == 'F) return false;
    }

    bool canMouseWin(vector<string>& grid, int catJump, int mouseJump) {
       memset(dp,-1,sizeof(dp));
        int r = grid.size(), c =grid[0].size();
        int catR, catC, mouseR, mouseC;
        for(int i=0; i<r; ++i){
            for(int j=0; j<c; ++j){
                if(grid[i][j] == 'C'){
                    catR = i, catC = j;
                }
                else if(grid[i][j] == 'M'){
                    mouseR = i, mouseC = j;
                }
            }
        }

        return solve(grid, catJump, mouseJump, catR, catC, mouseR, mouseC, 0);
    }
};

class Solution {
public:
    vector<int> productExceptSelf(vector<int>& nums) {
        vector<int>prefVector(nums.size(),1);
        vector<int>suffVector(nums.size(),1);
        int prefPro=1;
        for(int i=0;i<nums.size();i++){
            prefVector[i]=prefPro;
            prefPro*=nums[i];
        }
        int suffPro=1;
        for(int i=nums.size()-1;i>=0;i--){
            suffVector[i]=suffPro;
            suffPro*=nums[i];
        }
        vector<int>ans(nums.size());
        for(int i=0;i<nums.size();i++){
            ans[i]=prefVector[i]*suffVector[i];
        }
        return ans;
    }
};

class Solution {
public:
    int closetTarget(vector<string>& words, string target, int startIndex) {
         int ind= find(words.begin(),words.end(),target)-words.begin();
        int n= words.size();
        if (ind==n)return -1;
        if (words[startIndex]==target) return 0;
        int i= startIndex-1;
        int j= startIndex+1;
        int cnt1=0; int cnt2=0;
        while (true){
            cnt1++; cnt2++;
            if ((i>=0 && words[i%n]==target) || words[(n+i)%n]==target){
                return cnt1;
            }
            if ((j<n && words[j%n]==target) || words[(n+j)%n]==target){
                return cnt2;
            }
            i--; j++;
        }

        return -1;
    }
};

/**
 * Definition for singly-linked list.
 * struct ListNode {
 *     int val;
 *     ListNode *next;
 *     ListNode() : val(0), next(nullptr) {}
 *     ListNode(int x) : val(x), next(nullptr) {}
 *     ListNode(int x, ListNode *next) : val(x), next(next) {}
 * };
 */
class Solution {
public:
    vector<int> nodesBetweenCriticalPoints(ListNode* head) {
        ios_base::sync_with_stdio(false);
 if(head==NULL || head->next==NULL ||head->next->next==NULL){
     return {-1,-1};
 }
        ListNode* temp2=head->next;
        ListNode* temp3=head->next->next;
      vector<int>v;
      int i=2;
      while(temp3){
          if((head->val<temp2->val)&&(temp3->val<temp2->val)){
              v.push_back(i);
          }
          else if((head->val>temp2->val)&&(temp3->val>temp2->val)){
              v.push_back(i);
          }
          i++;
          head=head->next;
          temp2=temp2->next;
          temp3=temp3->next;
      }
      if(v.size()<2){
           return {-1,-1};
      }
      int mini=INT_MAX;
      for(int i=1;i<v.size();i++){
          mini=min(mini,(v[i]-v[i-1]));
      }
        return {mini,(v[v.size()-1]-v[0])};
    }
};

