        for(int i = 0 ; i < s.length(); i++)
        {
            if(s[i] == 'a' || s[i] == 'e' || s[i] == 'i' || s[i] == 'o' || s[i] == 'u
              || s[i] == 'A' || s[i] == 'E' || s[i] == 'O' || s[i] == 'I' || s[i] == 'U')
                v.push_back(s[i]);
        }
        reverse(v.begin(), v.end());
        int rev = 0;
        for(int i = 0 ; i < s.length(); i++)
        {
            if(s[i] = 'a' || s[i] = 'e' || s[i] = 'i' || s[i] = 'o' || s[i] = 'u
              || s[i] = 'A' || s[i] = 'E' || s[i] = 'O' || s[i] = 'I' || s[i] = 'U'){
                s[i] = v[rev];
                rev++;
            }
        }
        return s;
    }
};

class Solution {
public:
    void merge(int low, int mid, int high, vector<int> &nums) {
        if (low >= high) 
        return;
        int l = low, r = mid + 1, k = 0, size = high - low + 1;
        vector<int> sorted(size, 0);
        while (l <= mid and r <= high)
            sorted[k++] = nums[l] < nums[r] ? nums[l++] : nums[r++];
        while (l <= mid) 
            sorted[k++] = nums[l++];
        while (r <= high) 
            sorted[k++] = nums[r++];
        for (k = 0; k < size; k++)
            nums[k + low] = sorted[k];
    }

    void mergeSort(vector<int>& nums, int start, int end){
        if(start < end){
            int mid = start + (end - start) / 2;
            mergeSort(nums, start, mid);
            mergeSort(nums, mid + 1, end);
            merge(start, mid, end, nums);
        }
    }

    vector<int> sortArray(vector<int>& nums) {
        mergeSort(nums, 0, nums.size()-1);
        return nums;
    }
};

class Solution {
public:
    vector<int> shortestAlternatingPaths(int n,vector<vector<int>>&redEdges,vector<vector<int>>& blueEdges) 
    {
        multiset<int>temp;
        vector<multiset<int>>redchilds(n,temp),bluechilds(n,temp);
        for(auto j:redEdges)
        {
            redchilds[j[0]].insert(j[1]);
        }
        for(auto j:blueEdges)
        {
            bluechilds[j[0]].insert(j[1]);
        }
        vector<int>ans;
        for(int i=0;i<n;i++)
        {
            //BFS for all
            vector<multiset<int>>reds=redchilds,blues=bluechilds;
            queue<pair<char,int>>visit;
            visit.push({'n',0});//neutral='n'
            int steps=0;
            while(!visit.empty())
            {
                bool justbreak=false;
                int n=visit.size();
                for(int j=0;j<n;j++)
                {
                    pair<char,int>x=visit.front();
                    visit.pop();
                    if(x.second==i)
                    {
                        ans.push_back(steps);
                        justbreak=true;
                        break;
                    }
                    if(x.first=='n')
                    {
                        for(auto j:reds[x.second])
                        {
                            visit.push({'r',j});
                            auto itr1=reds[x.second].find(j);
                            reds[x.second].erase(itr1);
                        }
                        for(auto j:blues[x.second])
                        {
                            visit.push({'b',j});//blue='b'
                            auto itr1=blues[x.second].find(j);
                            blues[x.second].erase(itr1);
                        }
                    }
                    else if(x.first=='b')
                    {
                        for(auto j:reds[x.second])
                        {
                            visit.push({'r',j});//red='r'
                            auto itr1=reds[x.second].find(j);
                            reds[x.second].erase(itr1);
                        }
                    }
                    else if(x.first=='r')
                    {
                        for(auto j:blues[x.second])
                        {
                            visit.push({'b',j});
                            auto itr1=blues[x.second].find(j);
                            blues[x.second].erase(itr1);
                        }
                    }
                }
                if(justbreak)
                {
                    break;
                }
                steps++;
            }
            if(i==ans.size())
            {
                ans.push_back(-1);
            }
        }
        return ans;
    }
};

class Solution {
public:
    int findTargetSumWays(vector<int>& nums, int target) {
        // idx, target -> no of ways
        map<pair<int, int>, int> memo;
        return dp(nums, target, 0, memo); 
    }

private:
    int dp(vector<int>& nums, int target, int idx, map<pair<int, int>, int>& memo) {
        if (idx == nums.size()) return target == 0;
        if (memo.count({idx, target})) return memo[{idx, target}];

        int positive = dp(nums, target + nums[idx], idx + 1, memo);
        int negative = dp(nums, target - nums[idx], idx + 1, memo);

        return memo[{idx, target}] = positive + negative;
    }
};

