vector<long long> countBlackBlocks(int m, int n, vector<vector<int>>& cds) {
        vector<long long> ans(5,0);
        int sz=cds.size();
        set<pair<int,int>> s,black;
        for(int i=0;i<sz;++i){
            black.insert({cds[i][0],cds[i][1]});
        }
        for(int i=0;i<sz;++i){
            int x=cds[i][0],y=cds[i][1];
            // it can cover four squares
            // case 1
            if(x>0&&y>0){
                bool flag=true;
                int cnt=0;
                for(int dx=-1;dx<=0;++dx){
                    for(int dy=-1;dy<=0;++dy){
                        if(s.find({x+dx,y+dy})==s.end()){
                            if(black.find({x+dx,y+dy})!=black.end()){
                                cnt++;
                            } 
                        } else{
                            flag=false;
                            break;
                        } 
                    }
                }
                if(flag){
                    ans[cnt]++;
                }
            }
            // case 2
            if(x<m-1&&y>0){
                bool flag=true;
                int cnt=0;
                for(int dx=0;dx<=1;++dx){
                    for(int dy=-1;dy<=0;++dy){
                        if(s.find({x+dx,y+dy})==s.end()){
                            if(black.find({x+dx,y+dy})!=black.end()){
                                cnt++;
                            }
                        } else{
                            flag=false;
                            break;
                        } 
                    }
                }
                if(flag){
                    ans[cnt]++;
                }
            }
            // case 3
            if(x>0&&y<n-1){
                bool flag=true;
                int cnt=0;
                for(int dx=-1;dx<=0;++dx){
                    for(int dy=0;dy<=1;++dy){
                        if(s.find({x+dx,y+dy})==s.end()){
                            if(black.find({x+dx,y+dy})!=black.end()){
                                cnt++;
                            } 
                        } else{
                            flag=false;
                            break;
                        } 
                    }
                }
                if(flag){
                    ans[cnt]++;
                }
            }
            // case 4
            if(x<m-1&&y<n-1){
                bool flag=true;
                int cnt=0;
                for(int dx=0;dx<=1;++dx){
                    for(int dy=0;dy<=1;++dy){
                        if(s.find({x+dx,y+dy})==s.end()){
                            if(black.find({x+dx,y+dy})!=black.end()){
                                cnt++;
                            }
                        } else{
                            flag=false;
                            break;
                        } 
                    }
                }
                if(flag){
                    ans[cnt]++;
                }
            }
            // put in set
            s.insert({x,y});
        }
        ans[0]=(m-1)*1ll*(n-1)-ans[1]-ans[2]-ans[3]-ans[4];
        return ans;
    }
};

class Solution 
{
public:
    vector<int> closestPrimes(int left, int right) 
    {
        //marks all prime number from 2 to right using sieve algorithm
        vector<int> nums(right+1, 1);
        for(int i=2; i*i<=right; i++)
        {
            if(nums[i]==1)
            {
                for(int j=i*i; j<=right; j+=i)
                    nums[j]=0;
            }
        }

        //storing all prime number between left and right
        vector<int> prime;
        for(int i=max(2,left); i<=right; i++)
        {
            if(nums[i]==1) prime.push_back(i);
        }

        //finding pair of prime numbers having minimum difference
        int n1=-1, n2=-1, mini=1e8, diff;
        for(int i=1; i<prime.size(); i++)
        {
            diff = prime[i]-prime[i-1];
            if(diff < mini)
            {
                mini = diff;
                n1 = prime[i-1];
                n2 = prime[i];
            }
        }
        return {n1, n2};
    }
};

class Solution {
public:
    int maxLengthBetweenEqualCharacters(string s) {
        int v[26];
        memset(v,-1,sizeof v);
        int ans=-1;
        for(int i=0;i<s.size();i++){
            if(v[s[i]-'a']==-1){
                v[s[i]-'a']=i;
            }
            int res=i-v[s[i]-'a']-1;
            ans=max(ans,res);
        }
        return ans;
    }
};

