class Solution {
public:
    int closetTarget(vector<string>& words, string target, int startIndex) {
         int ind= find(words.begin(),words.end(),target)-words.begin();
        int n= words.size();
        if (ind==n)return -1;
        if (words[startIndex]==target) return 0;
        int i= startIndex-1;
        int j= startIndex+1;
        int cnt1=0; int cnt2=0;
        while (true){
            cnt1++; cnt2++;
            if ((i>=0 && words[i%n]==target) || words[(n+i)%n]==target){
                return cnt1;
            }
            if ((j<n && words[j%n]==target) || words[(n+j)%n]==target){
                return cnt2;
            }
            i--; j++;
        }

        return -1;
    }
};

class Solution {
public:
    long long minimumTotalCost(vector<int>& nums1, vector<int>& nums2) {
        long long ans = 0;

        vector<int> counts(100005, 0);
        int dominantCnt = 0;
        int dominantNum = -1;
        int involvedCnt = 0;
        int n = nums1.size();
        for (int i = 0; i < n; ++i) {
            if (nums1[i] == nums2[i]) {
                ans += i;
                counts[nums1[i]]++;
                if (counts[nums1[i]] > dominantCnt) {
                    dominantCnt = counts[nums1[i]];
                    dominantNum = nums1[i];
                }
                involvedCnt++;
            }
        }
        if (dominantCnt < involvedCnt / 2) {
            for (int i = 0; i < n; ++i) {
                if (nums1[i] != nums2[i] && nums1[i] != dominantNum && nums2[i] != dominantNum) {
                    counts[nums1[i]]++;
                    involvedCnt++;
                    ans += i;
                    if (dominantCnt <= involvedCnt / 2) {
                        return ans;
                    }
                }
            }
            return -1;
        }
        else {
            return ans;
        }
    }
};

