    vector<int> nodesBetweenCriticalPoints(ListNode* head) {
        ios_base::sync_with_stdio(false);
 if(head==NULL || head->next==NULL ||head->next->next==NULL){
     return {-1,-1};
 }
        ListNode* temp2=head->next;
        ListNode* temp3=head->next->next;
      vector<int>v;
      int i=2;
      while(head){
          if((head->val<temp2->val)&&(temp3->val<temp2->val)){
              v.push_back(i);
          }
          else if((head->val>temp2->val)&&(temp3->val>temp2->val)){
              v.push_back(i);
          }
          i++;
          head=head->next;
          temp2=temp2->next;
          temp3=temp3->next;
      }
      if(v.size()<2){
           return {-1,-1};
      }
      int mini=INT_MAX;
      for(int i=1;i<v.size();i++){
          mini=min(mini,(v[i]-v[i-1]));
      }
        return {mini,(v[v.size()-1]-v[0])};
    }
};

class Solution {
public:
    int chalkReplacer(vector<int>& chalk, int k) {
       long long sum =0;
       for(int i=0; i<chalk.size();i++){
           sum+=chalk[i];
       }

       if(k%sum == 0){
           int x = k%sum;
           for(int i=0; i<chalk.size();i++){
               x-=chalk[i];
               if(x<0){
                   return i;
                   break;
               }
           }
       }

       return 0;
    }
};

class Solution {
public:
    int rec(int ind,string &s,set<string>&st,vector<int>&dp)
    {
        if (ind==s.size()) return 0;
        if (dp[ind]!=-1) return dp[ind];
        int ans=s.size()-ind;
        for (int i=ind;i<s.size();i++)
        {
           string temp=s.substr(ind,i-ind+1);
           if (st.find(temp)!=st.end())
           {
              ans=min(ans,rec(i+1,s,st,dp));
           }
        }
        ans=min(ans,1+rec(ind+1,s,st,dp));
        return dp[ind]=ans;
    }
    int minExtraChar(string s, vector<string>& dictionary) 
    {
        set<string>st;
        int n=s.size();
        vector<int>dp(n,-1);
        for (auto it:dictionary)
        {
            st.insert(it);
        }
        return rec(0,s,st,dp);
    }
};

