class Solution {
public:

    int SumOfDivisor(vector<int>& nums, int Day){
        int sum = 0;
        for(int i = 1;i<nums.size();i++){
            sum += ceil((double)nums[i]/(double)(Day));
        }
        return sum;
    }
    int smallestDivisor(vector<int>& nums, int threshold) {
        int maxi = INT_MIN;
        for(int i = 0;i<nums.size();i++){
            maxi = max(maxi,nums[i]);
        }
        int low = 1,high = maxi,ans = -1;
        while(low <= high){
            int mid = (low + high)/2;
            if(SumOfDivisor(nums,mid) <= threshold){
                ans = mid;
                high = mid - 1;
            }
            else{
                low = mid + 1;
            }
        }
        return ans;
    }
};

/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
 * };
 */
class Solution {
public:
int sum = 0; // Initialised Sum
    void Traversal(TreeNode* root,int low,int high)
    {
        if(root==NULL) // If Node is NULL then we return 
        return;
        Traversal(root->left,low,high); // To check for left Node
        if(root->val <= high && root->val >=low)sum+=root->val;// If value of node is in range then add to sum.
        Traversal(root->right,low,high); // To check for right Node
    }
    int rangeSumBST(TreeNode* root, int low, int high) {
        ios_base::sync_with_stdio(false);
        cin.tie(nullptr);
        cout.tie(nullptr); // To make input output fast
        Traversal(root,low,high); //To Traverse in BST
        return sum;
    }
};

class Solution {
public:
    vector<int> grayCode(int n) {
        vector<int> res;
        res.push_back( 0 );
        for( int k = 0; k<n; k++ ) {
            int i = res.size(), t = (1<<k) ;
            while( i ) {
                int temp = res[--i] | t;
                res.push_back( temp );
            }
        }
        return res;
    }
};

class Solution {
public:
    int minCostClimbingStairs(vector<int>& cost) {
        int n = cost.size();

        for(int i=2; i<n; i++){
            cost[i] = min(cost[i-1],cost[i-2]) + cost[i];
        }

        return min(cost[n-1],cost[n-2]);
    }
};

class Solution {
public:
    bool validPath(int n, vector<vector<int>>& edges, int source, int destination) 
    {
        unordered_map<int,vector<int>> mp;
        for(auto i : edges)
        {
            vector<int> temp=i;
            int u=temp[0];
            int v=temp[1];
            mp[u].push_back(v);
            mp[v].push_back(u);
        }
        vector<bool> visited(n+1, false);
        queue<int>q;
        q.push(source);
        visited[source]=true;
        while(!q.empty())
        {
            int u=q.front();
            q.pop();
            for(auto i :mp[u])
            {
                if(visited[i]==false)
                {
                    q.push(i);
                }
            }
        }
        return visited[destination];    
    }
};

