class Solution {
    const int M = 1000000007;
    int mul(long long x, long long y) {
        return x * y % M;
    }

    int add(int x, int y) {
        if ((x += y) >= M) {
            x -= M;
        }
        return x; 
    }

public:
    int sumOfPower(vector<int>& nums) {
        sort(nums.begin(), nums.end());
        const int n = nums.size();
        int r = mul(mul(nums[0], nums[0]), nums[0]);
        for (int i = 1, last = 0; i < n; ++i) {
            last = add(nums[i - 1], add(last, last));
            r = add(r, mul(add(last, nums[i]), mul(nums[i], nums[i])));
        }

        return r;
    }
};

class Solution {
public:
    int longestWPI(vector<int>& hours) {
    map<int,int> mp;
    int k=0,ans=0;
    for(int i=0;i<hours.size();i++)
    {
        if(hours[i]>8)  k++; else   k--;
        if(k>0)
        {
        ans=max(ans,i+1);
        } else{
            if(mp.find(k-1)!=mp.end()){
                ans=max(ans,i-mp[k-1]);
            }
             if(mp.find(k)==mp.end()){
                mp[k]=i;
            }
        }

    }    
    return ans;
    }
};

class Solution {
public:
    vector<int> applyOperations(vector<int>& nums) {
        for(int i =0 ;i<nums.size()-1;i++){
            if(nums[i] == nums[i+1]){
                nums[i] *=2;
                nums[i+1] = 0;
            }
        };
        vector<int> ans;
        for(auto ele:nums){
            if(ele!=0)ans.push_back(ele);
        };
        for(auto ele:nums){
            if(ele == 0)ans.push_back(ele);
        };
        return ans;
    }
};

class Solution {
public:
    void find(vector<int>&v, int i, int e, int sum, vector<int>&sumv){
        if(i==e){
            sumv.push_back(sum);
            return;
        }

        find(v,i+1,e,sum+v[i
        +1]+v[i],sumv);
    }


    int minAbsDifference(vector<int>& nums, int goal) {
        int n=nums.size();

        //Step 1: Divide nums into 2 subarrays of size n/2 and n-n/2

        vector<int>A,B;
        for(int i=0;i<n/2;i++)
            A.push_back(nums[i]);
        for(int i=n/2;i<n;i++)
            B.push_back(nums[i]);

        //Step 2: Find all possible subset sums of A and B

        vector<int>sumA,sumB;
        find(A,0,A.size(),0,sumA);
        find(B,0,B.size(),0,sumB);

        sort(sumA.begin(),sumA.end());
        sort(sumB.begin(),sumB.end());

        //Step 3: Find combinations from sumA & sumB such that abs(sum-goal) is minimized

        int ans=INT_MAX;

        for(int i=0;i<sumA.size();i++){
            int s=sumA[i];
            int l=0;
            int r=sumB.size()-1;
            while(l<=r){
                int mid=l+(r-l)/2;
                int sum=s+sumB[mid];
                if(sum==goal)
                    return 0;
                ans=min(ans,abs(sum-goal));
                if(sum>goal){
                    r=mid-1;
                }
                else{
                    l=mid+1;
                }    
            }
        }

        return ans;
    }
};

