            x ^= 1;
            n = 0;
        }
        return root;
    }
};

class Solution {
public:
    void fliprow(int &r,vector<vector<int>>& grid) //function to toggle row
    {
        for(int i=0; i<grid[0].size(); i++){
            grid[r][i]=1-grid[r][i];
        }
    }

    void flipcol(int &c,vector<vector<int>>& grid){ //function to toggle column
        for(int j=0; j<grid.size(); j++){
            grid[j][c]=1-grid[j][c];
        }
    }

    int matrixScore(vector<vector<int>>& grid) {
        int n=grid.size();
        int m=grid[0].size();
//Making the MSB to 1, all values in column 0 should be 1 to get max value
        for(int i=0; i<n; i++){
            if(grid[i][0]==0){    
                fliprow(i,grid);
            }
        }
//traversing and checking which colums have more zeroes than 1, toggling them too
        for(int j=0; j<m; j++){
            int cnt0=0;
            int cnt1=0;
            for(int i=0; i<n; i++){
                if(grid[i][j]==0) cnt0++;
                else cnt1++;
            }
            if(cnt0>cnt1){
                flipcol(j,grid);
            }
        }
//finally calculating the ans
        int sum=0;
        for(int i=0; i<n; i++){
            for(int j=0; j<m; j++){
                if(grid[i][j]==1){
                    sum+= (1<<(m-j-1));
                }
            }
        }
        return sum;


    }
};

class Solution {
public:

    int countWithMergeSort(vector<long> &sums, int left, int right, int lower, int upper)
    {
        int count = 0;

        if(right - left <= 1)
        {
            if(right - left == 1)
            {
                return (lower <= sums[left] && sums[left] <= upper);
            }
            else
            {
                return 0;
            }
        }

        int mid = (left + right)/2;

        int leftSideSum = countWithMergeSort(sums, left, mid, lower, upper);
        int rightSideSum = countWithMergeSort(sums, mid, right, lower, upper);


        int i = left;
        int j = mid;

        int n = 0;
        int m = 0;

        vector<long> cache(right - left, 0);

        int k = 0;


        while(i < mid)
        {


            while(mid+n < right && sums[mid+n] < sums[i]+lower)
                {
                    n++;
                }

            while(mid+m < right && sums[mid+m] <= sums[i] + upper)
                {
                    m++;
                }

            while(j < right && sums[j] < sums[i])
            {
                cache[k++] = sums[j++];
            }

            cache[k++] = sums[i++];

            count += m-n;
        }


        while(j < right)
        {
            cache[k++] = sums[j++];
        }


        for(int idx = 0; idx<cache.size(); idx++)
        {
            sums[left + idx] = cache[idx];
        }

        return leftSideSum + rightSideSum + count;

    }

    int countRangeSum(vector<int>& nums, int lower, int upper) {

        vector<long> prefixSum(nums.size(),0);

        int n = nums.size();

        prefixSum[0] = nums[0];

        for(int i = 1; i<nums.size(); i++)
        {
            prefixSum[i] = nums[i] + prefixSum[i-1];
        }

        return countWithMergeSort(prefixSum, 0, n, lower, upper);
    }
};

