class Solution {
public:
    void bfs(int prevcolor,int row,int col,int color,vector<vector<int>>&visited,vector<vector<int>>&image)
    {
        // it'll ease the work
        queue<pair<int,int>> q;
        q.push({row,col});
        visited[row][col]=1;

        while(!q.empty())
        {
            row = q.front().first;
            col = q.front().second;
            q.pop();

            // if img is of the starting color.
            if(image[row][col]==prevcolor) image[row][col]=color;

            // up
            if(row-1>=0 && !visited[row-1][col] && image[row-1][col]==prevcolor) q.push({row-1,col}),visited[row-1][col]=1, image[row-1][col]=color;

            // right
            if(col+1<image[0].size() &&  !visited[row][col+1] && image[row][col+1]==prevcolor) q.push({row,col+1}),visited[row][col+1]=1, image[row][col+1]=color;

            //down
            if(row+1<image.size() && !visited[row+1][col] && image[row+1][col]==prevcolor) q.push({row+1,col}),visited[row+1][col]=1, image[row+1][col]=color;

            // left
            if(col-1>=0 && !visited[row][col-1] && image[row][col-1]==prevcolor) q.push({row,col-1}),visited[row][col-1]=1, image[row][col-1]=color;
        }
    }
    vector<vector<int>> floodFill(vector<vector<int>>& image, int sr, int sc, int color) {
          int prevcolor = image[sr][sc];

          // visiting array.
          vector<vector<int>> visited(image.size(),vector<int>(image[0].size(),0));

          bfs(prevcolor,sr,sc,color,visited,image);

          return image;
    }
};

class Solution {
public:
    bool buddyStrings(string s, string p) {
        int n=s.length(), m=p.length();
        if(n!=m) return false;

        vector<int> freq(26,0);

        int first=-1, second=-1;
        for(int i=0;i<n;i++){
            if(s[i] != p[i]){
                if(first==-1){
                    first=i;
                }else if(second==-1){
                    second=i;
                }else{
                    return false; // more than 2 mismatching characters
                }
            }
            freq[s[i]-'a']++;
        }

		// similar strings
        if(first == -1 && second == -1){
            for(int i=0;i<26;i++) if(freq[i] > 1) return true; // can swap similar characters
            return false; // all characters occur only once
        }else if(second == -1){
            return false; // exactly 1 mismatch
        }

        return (s[first]==p[second] && s[second]==p[first]); // check similarity on 2 mismatched indexes
    }
};

class Solution {
public:

    bool valid(int n, string s,int sum){
        // empty string indicates we have completed one partition
        if(s=="") if(sum==n) return true;

        // We use backtracking to check for all partitions if it is possible to generate required sum 
        // and if we find sum we immediately return true immediately
        for(int i=1;i<=s.size();i++){
            int x  = stoi(s.substr(0,i));
            if(valid(n, s.substr(i), sum+x)) return true;
        }

        //If no partition could add up to required sum n
        return false;
    }
    int punishmentNumber(int n) {
        int ans = 0;

        //generate all possible squares and check them if they satisfy the given statement
        for(int i=1;i<=n;i++){
            int sq = i*i;
            string x = to_string(sq);
            if(valid(i,x,0)) ans += i*i;
        }

        return ans;

    }
};

