class Solution {
public:
    int findTargetSumWays(vector<int>& nums, int target) {
        // idx, target -> no of ways
        map<pair<int, int>, int> memo;
        return dp(nums, target, 0, memo); 
    }

private:
    int dp(vector<int>& nums, int target, int idx, map<pair<int, int>, int>& memo) {
        if (idx == nums.size()) return target == 0;
        if (memo.count({idx, target})) return memo[{idx, target}];

        int positive = dp(nums, target + nums[idx], idx + 1, memo);
        int negative = dp(nums, target - nums[idx], idx + 1, memo);

        return memo[{idx, target}] = positive + negative;
    }
};

class Solution {
public:
    map<pair<int,int>,int> mp;
    void dfs(vector<vector<int>>& tree,vector<int>& possible,int cur ,int ans,int k)
    {
        for(auto& a:tree[cur])
        {
            if(possible[a]==-1)
            {
                int new_ans=ans;
                bool a1=false,a2=false;
                if(mp.find({a,cur})!=mp.end() && mp[{a,cur}]==0  )
                {
                    mp[{a,cur}]=1;
                    new_ans++;
                    a1=true;
                }
                if(mp.find({cur,a })!=mp.end() && mp[{cur,a}]==1  )
                {
                    mp[{cur,a}]=0;
                    new_ans--;
                    a2=true;
                }
                possible[a]=0;
                if(new_ans>=k)
                {
                    possible[a]=1;
                }
                dfs(tree,possible,a,new_ans,k);
                if(a1)
                {
                    mp[{a,cur}]=0;
                }
                if(a2)
                {
                    mp[{cur,a}]=1;
                }
            }
        }

    }
    int rootCount(vector<vector<int>>& edges, vector<vector<int>>& guesses, int k) {

        for(auto&e : guesses)
        {
            mp[ {e[0],e[1]}]=0;
        }
        int n=edges.size()+1;
        vector<vector<int>> tree(n);
        for(auto& e:edges)
        {
            tree[e[0]].push_back(e[1]);
            tree[e[1]].push_back(e[0]);
        }
        queue<int> q;
        q.push(0);
        vector<bool> visited(n,false);
        visited[0]=true;
        int ans=0;
        while(q.size()>0)
        {
            int a=q.front();
            q.pop();
            for(int i=0;i<tree[a].size();i++)
            {
                if(visited[tree[a][i]])
                    continue;
                visited[tree[a][i]]=true;
                if(mp.find({a,tree[a][i]})!=mp.end() && mp[{a,tree[a][i]}]==0  )
                {
                    mp[{a,tree[a][i]}]=1;
                    ans++;
                }
                if(mp.find({tree[a][i],a })!=mp.end() && mp[{tree[a][i],a}]==1  )
                {
                    mp[{tree[a][i],a}]=0;
                    ans--;
                }
                q.push(tree[a][i]);
            }
        }
        vector<int> possible(n,-1);
        possible[0]= (1?ans>=k:0);
        dfs(tree,possible,0,ans,k);
        int sum=accumulate(possible.begin(),possible.end(),0);
        return sum;
    }
};

class Solution {
public:
    bool isallsame(vector<vector<int>>&grid)
    {
        int compare=grid[0][0];
        for(int i=0;i<grid.size();i++)
        {
            for(int j=0;j<grid[0].size();j++)
            {
                if(grid[i][j]!=compare)
                {
                    return false;
                }
            }
        }
        return true;
    }
    int maxDistance(vector<vector<int>>&grid) 
    {
        if(isallsame(grid))
        {
            return -1;
        }
        vector<bool>a(grid[0].size(),false);
        vector<int>b(grid[0].size(),0);
        vector<vector<bool>>pushedinqueue(grid.size(),a);
        vector<vector<int>>distance(grid.size(),b);
        //BFS
        queue<pair<int,int>>visit;
        for(int i=0;i<grid.size();i++)
        {
            for(int j=0;j<grid[0].size();j++)
            {
                if(grid[i][j])
                {
                    visit.push({i,j});
                    pushedinqueue[i][j]=true;
                }
            }
        }
        int dist=0;
        while(!visit.empty())
        {
            int n=visit.size();
            for(int i=0;i<n;i++)
            {
                pair<int,int>x=visit.front();
                visit.pop();
                distance[x.first][x.second]=dist;
                if(x.first>0 && !pushedinqueue[x.first-1][x.second])
                {
                    pushedinqueue[x.first-1][x.second]=true;
                    visit.push({x.first-1,x.second});
                }
                if(x.first<(grid.size()-1) && !pushedinqueue[x.first+1][x.second])
                {
                    pushedinqueue[x.first+1][x.second]=true;
                    visit.push({x.first+1,x.second});
                }
                if(x.second>0 && !pushedinqueue[x.first][x.second-1])
                {
                    pushedinqueue[x.first][x.second-1]=true;
                    visit.push({x.first,x.second-1});
                }
                if(x.second<(grid[0].size()-1) && !pushedinqueue[x.first][x.second+1])
                {
                    pushedinqueue[x.first][x.second+1]=true;
                    visit.push({x.first,x.second+1});
                }
            }
            dist++;
        }
        int ans=INT_MIN;
        for(int i=0;i<grid.size();i++)
        {
            for(int j=0;j<grid[0].size();j++)
            {
                if(grid[i][j]==0)
                {
                    ans=max(ans,distance[i][j]);
                }
            }
        }
        return ans;
    }
};

