class Solution {
public:
    map<pair<int,int>,int> mp;
    void dfs(vector<vector<int>>& tree,vector<int>& possible,int cur ,int ans,int k)
    {
        for(auto& a:tree[cur])
        {
            if(possible[a]==-1)
            {
                int new_ans=ans;
                bool a1=false,a2=false;
                if(mp.find({a,cur})!=mp.end() && mp[{a,cur}]==0  )
                {
                    mp[{a,cur}]=1;
                    new_ans++;
                    a1=true;
                }
                if(mp.find({cur,a })!=mp.end() && mp[{cur,a}]==1  )
                {
                    mp[{cur,a}]=0;
                    new_ans--;
                    a2=true;
                }
                possible[a]=0;
                if(new_ans>=k)
                {
                    possible[a]=1;
                }
                dfs(tree,possible,a,new_ans,k);
                if(a1)
                {
                    mp[{a,cur}]=0;
                }
                if(a2)
                {
                    mp[{cur,a}]=1;
                }
            }
        }

    }
    int rootCount(vector<vector<int>>& edges, vector<vector<int>>& guesses, int k) {

        for(auto&e : guesses)
        {
            mp[ {e[0],e[1]}]=0;
        }
        int n=edges.size()+1;
        vector<vector<int>> tree(n);
        for(auto& e:edges)
        {
            tree[e[0]].push_back(e[1]);
            tree[e[1]].push_back(e[0]);
        }
        queue<int> q;
        q.push(0);
        vector<bool> visited(n,false);
        visited[0]=true;
        int ans=0;
        while(q.size()>0)
        {
            int a=q.front();
            q.pop();
            for(int i=0;i<tree[a].size();i++)
            {
                if(visited[tree[a][i]])
                    continue;
                visited[tree[a][i]]=true;
                if(mp.find({a,tree[a][i]})!=mp.end() && mp[{a,tree[a][i]}]==0  )
                {
                    mp[{a,tree[a][i]}]=1;
                    ans++;
                }
                if(mp.find({tree[a][i],a })!=mp.end() && mp[{tree[a][i],a}]==1  )
                {
                    mp[{tree[a][i],a}]=0;
                    ans--;
                }
                q.push(tree[a][i]);
            }
        }
        vector<int> possible(n,-1);
        possible[0]= (1?ans>=k:0);
        dfs(tree,possible,0,ans,k);
        int sum=accumulate(possible.begin(),possible.end(),0);
        return sum;
    }
};

class Solution {
private:
    static bool comp(vector<int>& it1, vector<int>& it2){
        if(it1[1] < it2[1] || (it1[1] == it2[1] && it1[2] < it2[2])) return true;
        return false;
    }
public:
    bool carPooling(vector<vector<int>>& trips, int capacity) {
        sort(trips.begin(),trips.end(),comp);
        int n = trips.size();
        int current_capacity = 0;
        priority_queue<pair<int,int>>pq;
        for(int i=0; i<n; i++){
            while(!pq.empty() && -1 * pq.top().first <= trips[i][1]){
                current_capacity -= pq.top().second;
                pq.pop();
            }
            current_capacity += trips[i][0];
            if(current_capacity > capacity) return false;
            pq.push({-trips[i][2],trips[i][0]});
        }
        return true;
    }
};

class Solution {
public:
    int lengthOfLIS(vector<int>& nums) {
        //array to store max length subsequence till that place
        vector<int> dp(nums.size(),0);
        int maxlength = 0;//to store maxlength of subsequence
        dp[0] = 1;//length will be 1 at first index 
        for(int i = 0;i<nums.size();i++){
            int currentMaxLen = 0; //to store maxlength at till this index
            for(int j = 0;j<i;j++){
                // only check when the subsequence is increasing
                if(nums[i]>nums[j]){
                    if(currentMaxLen<dp[j]){
                        currentMaxLen = dp[j]; //update currentMaxLen accordingly
                    }
                }
            }
            dp[i] = currentMaxLen + 1; //set the maxLength till ith index, which will be maxlenth so far + 1
            maxlength = max(maxlength,dp[i]); //update maxlength
        }

        return maxlength;
    }
};

