    void checkpalindrome(ListNode* Revhead){
        if(Revhead==NULL){
            return;
        }
         checkpalindrome(Revhead->next;
         if(Revhead!=NULL){
             if(Revhead->val!=Head->val){
                 flag=false;
             }
             Head=Head->next;
         }
