class DisjointSet{
public:
    vector<int>par,size;
    DisjointSet(int n){
        par.resize(n+1);
        size.resize(n+1,1);
        for(int i=0; i<=n; i++){
            par[i] = i;
        }
    }
    int findpar(int u){
        if(u == par[u) return u;
        return par[u] = findpar(par[u]);
    }

    void unionBySize(int u, int v){
        u = findpar(u);
        v = findpar(v);

        if(u == v) return;

        if(size[u] >= size[v]){
            par[v] = u;
            size[u] += size[v;
        }
        else{
            par[u] = v;
            size[v] += size[u];
        }
    }

};
class Solution {
public:
    bool hasValidPath(vector<vector<int>>& grid) {
        int n = grid.size();
        int m = grid[0].size();
        DisjointSet ds(n*m);
        for(int i=0; i<n; i++){
            for(int j=0; j<m; j++){
                int p = i * m + j;
                int p1 = (i-1)*m + j;  // 1
                int p2 = (i+1)*m + j;  // 1
                int p3 = i*m + (j+1);  // 2
                int p4 = i*m + (j-1);  // 2

                if(grid[i][j] == 1){
                    if(j+1 < m && (grid[i][j+1] == 1 || grid[i][j+1] == 3 || grid[i][j+1] == 5) ){
                        ds.unionBySize(p,p3);
                    }
                    if(j-1 >= 0 && (grid[i][j-1] == 1 || grid[i][j-1] == 4 || grid[i][j-1] == 6) ){
                        ds.unionBySize(p,p4);
                    }
                }
                else if(grid[i][j] == 2){
                    if(i+1 < n && (grid[i+1][j] == 2 || grid[i+1][j] == 5 || grid[i+1][j] == 6) ){
                        ds.unionBySize(p,p2);
                    }

                    if(i-1>=0 && (grid[i-1][j] == 2 || grid[i-1][j] == 3 || grid[i-1][j] == 4)){
                        ds.unionBySize(p,p1);
                    }
                }
                else if(grid[i][j] == 3){
                    if(j-1 >= 0 && (grid[i][j-1] == 1 || grid[i][j-1] == 4 || grid[i][j-1] == 6) ){
                        ds.unionBySize(p,p4);
                    }
                    if(i+1 < n && (grid[i+1][j] == 2 || grid[i+1][j] == 5 || grid[i+1][j] == 6) ){
                        ds.unionBySize(p,p2);
                    }
                }
                else if(grid[i][j] == 4){
                    if(j+1 < m && (grid[i][j+1] == 1 || grid[i][j+1] == 3 || grid[i][j+1] == 5) ){
                        ds.unionBySize(p,p3);
                    }
                    if(i+1 < n && (grid[i+1][j] == 2 || grid[i+1][j] == 5 || grid[i+1][j] == 6) ){
                        ds.unionBySize(p,p2);
                    }
                }
                else if(grid[i][j] == 5){
                    if(i-1>=0 && (grid[i-1][j] == 2 || grid[i-1][j] == 3 || grid[i-1][j] == 4)){
                        ds.unionBySize(p,p1);
                    }
                    if(j-1 >= 0 && (grid[i][j-1] == 1 || grid[i][j-1] == 4 || grid[i][j-1] == 6) ){
                        ds.unionBySize(p,p4);
                    }
                }
                else if(grid[i][j] == 6){
                    if(i-1>=0 && (grid[i-1][j] == 2 || grid[i-1][j] == 3 || grid[i-1][j] == 4)){
                        ds.unionBySize(p,p1);
                    }
                    if(j+1 < m && (grid[i][j+1] == 1 || grid[i][j+1] == 3 || grid[i][j+1] == 5) ){
                        ds.unionBySize(p,p3);
                    }
                }
            }
        }
        return ds.findpar(0) == ds.findpar(n*m-1);
    }
};

class Solution {
public:
    vector<int> goodDaysToRobBank(vector<int>& arr, int k) {

        int n = arr.size();

        // left[i] will store the length of increasing subarray including arr[i] on left side

        vector<int> left(n, 1);

        // fill left array

        for(int i = 1; i < n; i++)
        {
            if(arr[i] <= arr[i - 1]) {
                left[i] = left[i - 1] + 1;
        }

        // right[i] will store the length of increasing subarray including arr[i] on right side

        vector<int> right(n, 1);

        // fill right array

        for(int i = n - 2; i >= 0; i--) {
            if(arr[i] <= arr[i + 1]) {
                right[i] = right[i + 1] + 1;
        }

        // push the possible index into res

        vector<int> res;

        for(int i = k; i <= n - k - 1; i++) {
            if(left[i] >= k + 1 && right[i] >= k + 1) {
                res.push_back(i);
            }
        }

        return res;
    }
};

class Solution {
public:
    int performOperation(string operation, int firstNumber, int secondNumber) {
        if(operation == "+") {
            return secondNumber + firstNumber; 
        if(operation == "-")    
            return secondNumber - firstNumber; 
        if(operation == "*")
            return secondNumber * firstNumber; 
        return secondNumber / firstNumber; 
    }
    int evalRPN(vector<string>& tokens) {
        stack<int> tokenStack;
        set<string> operators = {"+", "-", "*", "/"};

        for(int i = 0; i < tokens.size(); i++)
        {
            // if the token is an operator 
            if(operators.find(tokens[i]) != operators.end())
            {
                // pop the 2 numbers in the stack 
                int firstNumber = tokenStack.top();
                tokenStack.pop();
                int secondNumber = tokenStack.top(); 
                tokenStack.pop();

                // do the operation on the two numbers
                int operationResult = performOperation(tokens[i], firstNumber, secondNumber); 

                // push the result of the operation in the stack 
                tokenStack.push(operationResult); 
            }
            else
            {
                // if the token is a number, push it to the stack
                tokenStack.push(stoi(tokens[i])); 
            }
        }
        return tokenStack.top();
    }
};

