class Solution {
public:
    int mod=1e9+7;
    vector<int>prime;
    int mp[45];
    long long dp[31][1<<12];
    int find(int n)
    {
        for(int i=2;i<=sqrt(n);i++)
        {
            if(n%i==0)
            {
                return false;
            }
        }
        return true;
    }
    long long find(int value,int mask)
    {
        if(value>30)
        {
            return (mask>0);
        }
        if(dp[value][mask]!=-1)
        {
            return dp[value][mask]%mod;
        }
        int new_mask=0;
        long long product=1;
        for(int i=0;i<prime.size();i++)
        {
            if((value%prime[i])==0)
            {
                product*=prime[i];
                new_mask|=(1<<i);
            }
        }
        long long ans=find(value+1,mask);
        if(product==value&&mp[value]&&((mask&new_mask)==0)
        {
            ans+=(find(value+1,mask|new_mask)*mp[value]);
        }
        return dp[value][mask]=ans%mod;
    }
    int numberOfGoodSubsets(vector<int>& nums) 
    {
        memset(dp,-1,sizeof(dp));
        for(int i=2;i<=30;i++)
        {
            if(find(i))
            {
                prime.push_back(i);
            }
        }
        for(auto it:nums)
        {
            mp[it]++;
        }
        long long val=find(2,0)%mod;
        long one=1;
        for(int i=0;i<mp[1];i++)
        {
            one=(one*2)%mod;
        }
        val=(val*one)%mod;
        return val;
    }
};

class Solution {
public:
    bool isNumber(string s) {
        int n = s.length();
        int i = 0;

        // Skip leading white space
        while (i < n && isspace(s[i])) {
            i++;
        }

        // Check optional sign
        if (i < n && (s[i] == '+' || s[i] == '-')) {
            i++;
        }

        // Check digits before decimal point
        bool hasDigits = false;
        while (i < n && isdigit(s[i])) {
            i++;
            hasDigits = true;
        }

        // Check optional decimal point and digits after it
        if (i < n && s[i] == '.') {
            i++;
            while (i < n && isdigit(s[i])) {
                i++;
                hasDigits = true;
            }
        }

        // Check optional exponent part
        if (hasDigits && i < n && (s[i] == 'e' || s[i] == 'E')) {
            i++;

            // Check optional sign in exponent
            if (i < n && (s[i] == '+' || s[i] == '-')) {
                i++;
            }

            bool hasExponentDigits = false;
            while (i < n && isdigit(s[i])) {
                i++;
                hasExponentDigits = true;
            }

            // The exponent must have at least one digit
            if (!hasExponentDigits) {
                return false;
            }
        }

        // Check trailing white space
        while (i < n && isspace(s[i])) {
            i++;
        }

        // The number is valid if we consumed the entire string and found at least one digit
        return i == n && hasDigits;
    }
};

class Solution {
public:
    #define mod 1000000007
    long long dp[102][10][2][2];
    long long f(string &r,int n,int pre,int leadingZero,int tight){
        if(n==0) return 1;

        if(dp[n][pre][leadingZero][tight]!=-1) return dp[n][pre][leadingZero][tight];
        long long up = tight ? (r[r.size()-n]-'0'):9,ans=0;

        if(leadingZero){
            for(int i=0;i<=up;i++){
                ans = (ans + f(r,n-1,i,(i==0),tight&(i==up)))%mod; 
            }
        } else {
            if(pre-1>=0 && pre-1<=up) ans = (ans + f(r,n-1,pre-1,0,tight&(pre-1==up)))%mod;
            if(pre+1<=up) ans = (ans + f(r,n-1,pre+1,0,tight&(pre+1==up)))%mod;
        }


        return dp[n][pre][leadingZero][tight]=ans;
    }
    int countSteppingNumbers(string low, string high) {
        int n=high.size();
        memset(dp,-1,sizeof(dp));
        long long r= f(high,high.size(),0,1,1);
        memset(dp,-1,sizeof(dp));
