            if((low[i]-'0')>0){
                low[i]--;break;
            } else {
                low[i]='9';
            }
        }

        // cout<<low<<endl;
        long long l= f(low,low.size(),0,1,1);
        cout<<l<<" "<<r<<endl;
        return (r-l+mod)%mod;
    }
