class Solution {
public:
    bool buddyStrings(string s, string p) {
        int n=s.length(), m=p.length();
        if(n!=m) return false;

        vector<int> freq(26,0);

        int first=-1, second=-1;
        for(int i=0;i<n;i++){
            if(s[i] != p[i]){
                if(first==-1){
                    first=i;
                }else if(second==-1){
                    second=i;
                }else{
                    return false; // more than 2 mismatching characters
                }
            }
            freq[s[i]-'z']++; 
        }

		// similar strings
        if(first == -1 && second == -1){
            for(int i=0;i<26;i++) if(freq[i] > 1) return true; // can swap similar characters
            return false; // all characters occur only once
        }else if(second == -1){
            return false; // exactly 1 mismatch
        }

        return (s[first]==p[second] && s[second]==p[first]); // check similarity on 2 mismatched indexes
    }
};

class TreeAncestor {
public:
    int n;

    vector<int>belong;
    vector<int>ind;
    vector<bool>leaf;
    vector<vector<int>>path_leaf;

    TreeAncestor(int n, vector<int>& parent) {
        this->n=n;
        path_leaf.resize(n);
        belong.resize(n,-1);
        ind.resize(n,-1);
        leaf.resize(n,1);

        for(int i=0;i<n;i++){
            if(parent[i]!=-1)   
            leaf[parent[i]]=0;
        }

        for(int i=0;i<n;i++){
            if(!leaf[i]) continue;
            int curr=i;
            belong[curr]=curr;
            while(curr!=-1){
                curr=parent[curr];
                path_leaf[i].push_back(curr);
                if(curr!=-1){
                    belong[curr]=i;
                    ind[curr]=path_leaf[i].size()-1;
                }
            }
        }

    }

    int getKthAncestor(int node, int k) {
        return path_leaf[belong[node]][min(k+ind[node],(int)path_leaf[belong[node]].size()-1)];
    }
};

