class Solution {
public:
    int longestValidSubstring(string word, vector<string>& forbidden) {
        vector<int> ends(word.size() , -1);
        unordered_map<string, int> forbidden_word;
        for(auto it : forbidden)forbidden_word[it] = 1;
        int n = word.size();
        for(int i = 0; i<n; i++){
            string temp = "";
            for(int j = i; j<i+10 && j<n; j++){
                temp += word[j];
                if(forbidden_word.find(temp) != forbidden_word.end()) {
                    ends[j] = i;
                }
            }
        }

        int i = 0, j = 0;
        int ans = INT_MIN;
        while(j < n){

            if(ends[j] != -1){
                int st = ends[j];
                if(st < i){
                    ans = max(ans, j-i+1);
                }
                else{
                    i = st+1;
                    ans = max(ans, j-i+1);
                }
            }
            else ans = max(ans,j-i+1);
            j++;
        }
        return ans;
    }
};

class Solution {
public:
    int maxIncreasingCells(vector<vector<int>>& mat) {
        int n = mat.size(), m = mat[0].size();
        vector<int> row_max(n), col_max(m);

        map<int, vector<pair<int, int>>, greater<int>> pos;
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < m; ++j) {
                pos[mat[i][j]].push_back({i, j});
            }
        }

        int ans = 0;
        for (auto& [num, cells]: pos) {
            int k = cells.size();
            vector<int> next(k);
            for (int i = 0; i < k; ++i) {
                int r = cells[i].first, c = cells[i].second;
                next[i] = min(row_max[r], col_max[c]) + 1;
                ans = max(ans, next[i]);
            }
            for (int i = 0; i < k; ++i) {
                int r = cells[i].first, c = cells[i].second;
                row_max[r] = max(row_max[r], next[i]);
                col_max[c] = max(col_max[c], next[i]);
            }
        }
        return ans;
    }
};

class Solution {
public:
    vector<int> nodesBetweenCriticalPoints(ListNode* head) {
        vector<int> ans={-1,-1};
        ListNode* prev=head;
        if(!prev) return ans;
        ListNode* curr=prev->next;
        if(!curr) return ans;
        ListNode* next=curr->next;
        if(!next) return ans;

        int first=-1;
        int last=-1;
        int mind=INT_MAX;
        int i=1;
        while(next){
            bool iscp=((curr->val>prev->val && curr->val>next->val)||(curr->val<prev->val&&curr->val<next->val))?true:false;
            if(iscp&&first==-1){
                first=i;
                last=i;
            }
            else if(iscp){
                mind=min(mind,i-last);
                last=i;
            }
            i++;
            prev=curr;
            curr=next;
            next=next->next;
        }
        if(first==last)
         return ans;
         else
         {
             ans[0]=mind;
             ans[1]=last-first;
         }
         return ans;
    }
};

