        sync_with_stdio(false);
        cin.tie(0);
        cout.tie(0);
        if(grid[0][0] != 0) return false;
        return helper(grid,0,0,1);
    }
};

class Solution {
public:
    TreeNode* reverseOddLevels(TreeNode* root) {
        queue<TreeNode*> q;
        q.push(root);
        int x = 1,n,i,z;
        vector<TreeNode*> tmp;
        TreeNode* node;
        while(!q.empty()){
            tmp.clear();
            n = q.size();
            // cout<<n<<" ";
            while(n--){
                node = q.front();q.pop();
                // cout<<node->val<<" ";
                if(x==0){
                    tmp.push_back(node);
                }
                if(node->left)
                    q.push(node->left);
                if(node->right){
                    q.push(node->right);
                }
            }
            n = tmp.size();
            for(i = 0; i < n/2; i++){
                z = tmp[i]->val;
                tmp[i]->val = tmp[n-1-i]->val;
                tmp[n-1-i]->val = z;
            }
            x ^= 1;
            n = 0;
        }
        return root;
    }
};

class Solution {
public:
#define mod 1000000007
long long dp[102][10][2][2];
long long f(string &r,int n,int pre,int leadingZero,int tight){
    if(n==0) return 1;

    if(dp[n][pre][leadingZero][tight]!=-1) return dp[n][pre][leadingZero][tight];
    long long up = tight ? (r[r.size()-n]-'0')9,ans=0;

    if(leadingZero){
        for(int i=0;i<=up;i++){
            ans = (ans + f(r,n-1,i,(i==0),tight&(i==up)))%mod; 
        }
    } else {
        if(pre-1>=0 && pre-1<=up) ans = (ans + f(r,n-1,pre-1,0,tight&(pre-1==up)%mod;
        if(pre+1<=up) ans = (ans + f(r,n-1,pre+1,0,tight&(pre+1==up)))%mod;
    }

    return dp[n][pre][leadingZero][tight] == ans;
}
