class Solution {
public:
    void bfs(int prevcolor,int row,int col,int color,vector<vector<int>>&visited,vector<vector<int>>&image)
    {
        // it'll ease the work
        queue<pair<int,int>> q;
        q.push({row,col});
        visited[row][col]=1;

        while(!q.empty())
        {
            row = q.front().first;
            col = q.front().second;
            q.pop();

            // if img is of the starting color.
            if(image[row][col]==prevcolor) image[row][col]=color;

            // up
            if(row-1>=0 && !visited[row-1][col] && image[row-1][col]==prevcolor) q.push({row-1,col}),visited[row-1][col]=1, image[row-1][col]=color;

            // right
            if(col+1<image[0].size() &&  !visited[row][col+1] && image[row][col+1]==prevcolor) q.push({row,col+1}),visited[row][col+1]=1, image[row][col+1]=color;

            //down
            if(row+1<image.size() && !visited[row+1][col] && image[row+1][col]==prevcolor) q.push({row+1,col}),visited[row+1][col]=1, image[row+1][col]=color;

            // left
            if(col-1>=0 && !visited[row][col-1] && image[row][col-1]==prevcolor) q.push({row,col-1}),visited[row][col-1]=1, image[row][col-1]=color;
        }
    }
    vector<vector<int>> floodFill(vector<vector<int>>& image, int sr, int sc, int color) {
          int prevcolor = image[sr][sc];

          // visiting array.
          vector<vector<int>> visited(image.size(),vector<int>(image[0].size(),0));

          bfs(prevcolor,sr,sc,color,visited,image);

          return image;
    }
};

class Solution {
public:
    int func(int i,int l,vector<int>&obstacles,vector<vector<int>>&dp){
        if(i==obstacles.size()-2){
            if(obstacles[i+1]==l)return 1;
            return 0;
        }

        if(dp[i][l]!=-1)return dp[i][l];

        if(obstacles[i+1]!=l){
            return dp[i][l] = func(i+1,l,obstacles,dp);
        }


        int b=INT_MAX;
        for(int j=1;j<=3;j++){
            if(l==j)continue;
            if(obstacles[i]==j)continue;
            b=min(b,1+func(i,j,obstacles,dp));
        }


        return dp[i][l] = b;
    }

    int minSideJumps(vector<int>& obstacles) {
        int n=obstacles.size();
        vector<vector<int>>dp(n,vector<int>(4,-1));
        return func(0,2,obstacles,dp);
    }
};

class Solution {
public:
    #define mod 1000000007
    long long dp[102][10][2][2];
    long long f(string &r,int n,int pre,int leadingZero,int tight){
        if(n==0) return 1;

        if(dp[n][pre][leadingZero][tight]!=-1) return dp[n][pre][leadingZero][tight];
        long long up = tight ? (r[r.size()-n]-'0'):9,ans=0;

        if(leadingZero){
            for(int i=0;i<=up;i++){
                ans = (ans + f(r,n-1,i,(i==0),tight&(i==up)))%mod; 
            }
        } else {
            if(pre-1>=0 && pre-1<=up) ans = (ans + f(r,n-1,pre-1,0,tight&(pre-1==up)))%mod;
            if(pre+1<=up) ans = (ans + f(r,n-1,pre+1,0,tight&(pre+1==up)))%mod;
        }


        return dp[n][pre][leadingZero][tight]=ans;
    }
    int countSteppingNumbers(string low, string high) {
        int n=high.size();
        memset(dp,-1,sizeof(dp));
        long long r= f(high,high.size(),0,1,1);
        memset(dp,-1,sizeof(dp));
        for(int i=low.size()-1;i>=0;i--){
            if((low[i]-'0')>0){
                low[i]--;break;
            } else {
                low[i]='9';
            }
        }

        // cout<<low<<endl;
        long long l= f(low,low.size(),0,1,1);
        cout<<l<<" "<<r<<endl;
        return (r-l+mod)%mod;
    }
};

