/**
 * Definition for singly-linked list.
 * struct ListNode {
 *     int val;
 *     ListNode *next;
 *     ListNode() : val(0), next(nullptr) {}
 *     ListNode(int x) : val(x), next(nullptr) {}
 *     ListNode(int x, ListNode *next) : val(x), next(next) {}
 * };
 */
class Solution {
public:
    ListNode* addTwoNumbers(ListNode* l1, ListNode* l2) {
        //initializing tem and temp so that l1 and l2 reamins preserved,
        //though this isn't needed but it a good practice
        ListNode* temp=l1;
        ListNode* tem=l2;
        ListNode *ans;
        ListNode *head;
        int carry=0;
        int valu;
        //initiallize the first node of answer
        int sum=tem->val+temp->val+carry;
        valu=sum%10;
        carry=sum/10;
        ListNode* node =new ListNode(valu);
        ans=node;
        head=ans;
        tem=tem->next;
        temp=temp->next;
        while(tem!=NULL && temp!=NULL)
        {
            sum=tem->val+temp->val+carry;
            valu=sum%10;
            carry=sum/10;
            ListNode* node =new ListNode(valu);
            ans->next=node;
            ans=ans->next;
            temp=temp->next;
            tem=tem->next;
        }
        //if l1 gets over and there are still some elements in l2
        if(tem==NULL && temp!=NULL)
        {
            while(temp!=NULL)
            {
                sum=temp->val+carry;
                valu=sum%10;
                carry=sum/10;
                ListNode* node =new ListNode(valu);
                ans->next=node;
                ans=ans->next;
                temp=temp->next;
            }
        }
        //if l2 gets over and there are still some elements in l1
        if(tem!=NULL && temp==NULL)
        {
            while(tem!=NULL)
            {
                sum=tem->val+carry;
                valu=sum%10;
                carry=sum/10;
                ListNode* node =new ListNode(valu);
                ans->next=node;
                ans=ans->next;
                tem=tem->next;
            }
        }
        //if there is still a carry left
        if(carry!=0)
        {
            ListNode* node =new ListNode(carry);
            ans->next=node;
        }
        return head;
    }
};

class Solution {
public:
    void find(vector<int>&v, int i, int e, int sum, vector<int>&sumv){
        if(i==e){
            sumv.push_back(sum);
            return;
        }
        find(v,i+1,e,sum+v[i],sumv);
        find(v,i+1,e,sum,sumv);
    }


    int minAbsDifference(vector<int>& nums, int goal) {
        int n=nums.size();

        //Step 1: Divide nums into 2 subarrays of size n/2 and n-n/2

        vector<int>A,B;
        for(int i=0;i<n/2;i++)
            A.push_back(nums[i]);
        for(int i=n/2;i<n;i++)
            B.push_back(nums[i]);

        //Step 2: Find all possible subset sums of A and B

        vector<int>sumA,sumB;
        find(A,0,A.size(),0,sumA);
        find(B,0,B.size(),0,sumB);

        sort(sumA.begin(),sumA.end());
        sort(sumB.begin(),sumB.end());

        //Step 3: Find combinations from sumA & sumB such that abs(sum-goal) is minimized

        int ans=INT_MAX;

        for(int i=0;i<sumA.size();i++){
            int s=sumA[i];
            int l=0;
            int r=sumB.size()-1;
            while(l<=r){
                int mid=l+(r-l)/2;
                int sum=s+sumB[mid];
                if(sum==goal)
                    return 0;
                ans=min(ans,abs(sum-goal));
                if(sum>goal){
                    r=mid-1;
                }
                else{
                    l=mid+1;
                }    
            }
        }

        return ans;
    }
};

