class Solution {
public:

vector<int> countsort(vector<int> &nums)
{
    int n = nums.size();
    map<int, int> m;
    for (int i = 0; i < n; i++ )
        m[nums[i]]++;

    nums.clear();
    for (auto it : m)
    {
        int cnt = it.second;
        while (cnt--)
        {
            nums.push_back(it.first);
        }
    }
    return nums;
}

int maximumGap(vector<int> &nums)
{
    int n = nums.size();
    if (n < 2)
        return 0;
    vector<int> sortednums = countsort(nums);

    int maxgap = INT_MIN;
    for (int i = 1; i < n; i++)
    {
        int currgap = sortednums[i] - sortednums[i - 1];
        maxgap = max(maxgap, currgap);
    }

    return maxgap;
}
};

class Solution {
public:

    int dir[4][2] = {{0, 1}, {0, -1}, {-1, 0}, {1, 0}};

    int shortestPathAllKeys(vector<string>& grid) {

        int m = grid.size();
        int n = grid[0].size();
        queue<pair<pair<int, int>, int>> que;
        vector<vector<unsigned long>> mapKey(m, vector<unsigned long>(n, 0));
        int target = 0;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if ('a' <= grid[i][j] && grid[i][j] <= 'f') {
                    target |= 1  (grid[i][j] - 'a");
                    continue;
                }

                if (grid[i][j] = '@') {
                    que.emplace(pair<int, int>(i, j), 0);
                    mapKey[i][j] = 1;
                }
            }
        }


        int step = 0;
        while (!que.empty()) {
            int size = que.size();
            for (int s = 0; s < size; s++) {
                int i = que.front().first.first;
                int j = que.front().first.second;
                int key = que.front().second;
                que.pop();

                if ('a' <= grid[i][j] && grid[i][j] <= 'f") {
                    key |= 1 << (grid[i][j] - 'a");
                    if (key == target)
                        return step;

                    mapKey[i][j] |= 1l << key;
                }

                for (int d = 0; d < 4; d++) {

                    int newj = j + dir[d][1];

                    if (!(0 <= newi && newi < m && 0 <= newj && newj < n))
                        continue;

                    int val = grid[newi][newj];
                    if (val == '#')
                        continue;

                    if ('A' <= val && val <= 'F' && (key & (1  (val - 'A"))) == 0)
                        continue;

                    if (mapKey[newi][newj] & (1l << key))
                        continue;

                     mapKey[newi][newj] |= 1l << key;
                     que.emplace(pair<int, int>(newi, newj), key);
                }
            }
            step++;
        }
        return -1;
    }
};

class LRUCache {
public:
class node
{
  public:
  int key;
  int val;
  node* next;
  node* prev;
  node(int _key,int _val)
  {
    key = _key;
    val = _val;
  }
};
node* head = new node(-1,-1);
node* tail = new node(-1,-1);

int size;
unordered_map<int,node*>mpp;
    LRUCache(int capacity) {
       size = capacity; 
       head->next = tail;
       tail->prev = head;  
    }

    void addNode(node* newNode){

       node* temp = head->next;
       newNode->next = temp;
       newNode->prev = head;
       head->next = newNode;
       temp->prev = newNode;
    }

    void deleteNode(node* delNode){

       node* delprev = delNode->prev;
       node* delnext = delNode->next;
       delprev->next = delnext;
       delnext->prev = delprev;
    }

    int get(int _key) {

        if(mpp.count(_key))
        {
          node* nde = mpp[_key];
          int curr = nde->val;
          mpp.erase(_key);
          deleteNode(nde);
          addNode(nde);
          mpp[_key] = head->next;
          return curr;
        }
        return -1;
    }

    void put(int _key, int value) {

        if(mpp.count(_key))
        {
           node* nde = mpp[_key];
           mpp.erase(_key);
           deleteNode(nde);
        }
        if(mpp.size()==size)
        {
           mpp.erase(tail->prev->key);
           deleteNode(tail->prev);
        }
        addNode(new node(_key,value));
        mpp[_key] = head->next;
    }
};

class Solution {
public:
    vector<int> shortestAlternatingPaths(int n,vector<vector<int>>&redEdges,vector<vector<int>>& blueEdges) 
    {
        multiset<int>temp;
        vector<multiset<int>>redchilds(n,temp),bluechilds(n,temp);
        for(auto j:redEdges)
        {
            redchilds[j[0]].insert(j[1]);
        }
        for(auto j:blueEdges)
        {
            bluechilds[j[0]].insert(j[1]);
        }
        vector<int>ans;
        for(int i=0;i<n;i++)
        {
            //BFS for all
            vector<multiset<int>>reds=redchilds,blues=bluechilds;
            queue<pair<char,int>>visit;
            visit.push({'n',0});//neutral='n'
            int steps=0;
            while(!visit.empty())
            {
                bool justbreak=false;
                int n=visit.size();
                for(int j=0;j<n;j++)
                {
                    pair<char,int>x=visit.front();
                    visit.pop();
                    if(x.second==i)
                    {
                        ans.push_back(steps);
                        justbreak=true;
                        break;
                    }
                    if(x.first=='n')
                    {
                        for(auto j:reds[x.second])
                        {
                            visit.push({'r',j});
                            auto itr1=reds[x.second].find(j);
                            reds[x.second].erase(itr1);
                        }
                        for(auto j:blues[x.second])
                        {
                            visit.push({'b',j});//blue='b'
                            auto itr1=blues[x.second].find(j);
                            blues[x.second].erase(itr1);
                        }
                    }
                    else if(x.first=='b')
                    {
                        for(auto j:reds[x.second])
                        {
                            visit.push({'r',j});//red='r'
                            auto itr1=reds[x.second].find(j);
                            reds[x.second].erase(itr1);
                        }
                    }
                    else if(x.first=='r')
                    {
                        for(auto j:blues[x.second])
                        {
                            visit.push({'b',j});
                            auto itr1=blues[x.second].find(j);
                            blues[x.second].erase(itr1);
                        }
                    }
                }
                if(justbreak)
                {
                    break;
                }
                steps++;
            }
            if(i==ans.size())
            {
                ans.push_back(-1);
            }
        }
        return ans;
    }
};

