        i = row + 2;
        j = col - 1;
        if(i<n && j>=0 && grid[i][j] == num) return helper(grid,i,j,num+1);

        i = row + 2;
        j = col + 1;
        if(i<n && j<n && grid[i][j] == num) return helper(grid,i,j,num+1);

        i = row + 1;
        j = col + 2;
