        if(prev){
            return dp[idx][prev]=(s[idx]=='0')+solve(idx+1,prev,s,dp);
        }
        else{
            return dp[idx][prev]=min((s[idx]==1)+solve(idx+1,0,s,dp),(s[idx]=='0')+solve(idx+1,1,s,dp));
        }
    }
