        if(x==1)return false;
        for(int i = 2; i*i<=x; i++){
            if(x%i==0)return false;
        }
        return true;
    }
    int diagonalPrime(vector<vector<int>>& nums) {
        int i,ans=0,n=nums.size();
        for(i = 0; i < n; i++){
            if(check(nums[i][i]) && nums[i][i]>ans){
                ans = nums[i][i];
            }
            if(check(nums[i][n-1-i]) && nums[i][n-1-i]>ans){
                ans = nums[i][n-1-i];
            }
        }
        return ans;
    }
};

class Solution {
public:
    bool queryString(string s, int n)
     {
        unordered_set<int> seen;
        int len = s.length();
        for(int i=len-1;i>=0;i--)
        {
            int num = 0;
            for(int j=1;j<=min(len-i,31);j++)
            { 
                num = num*2 + (s[i+j-1] == '1' ? 1 : 0);
                if(0 < num && num <= n) seen.insert(num);
            }
            if(seen.size() == n) return true;
        }
        return false;
    }
};

