class Solution {
public:
    string smallestString(string s) {
        int temp = -1;
        int cnt = 0;
        for(int i = 0; i < s.size(); i++)
        {
            if(s[i] == 'a')
            {
                cnt++;
            }
        }
        if(cnt == s.size())
        {
            s[s.size() - 1] = 'z';
            return s;
        }
        else
        {
            for(int i = 0; i < s.size(); i++)
            {
                if(s[i] == 'a')
                {
                    temp = i;
                    break;
                }
            }

            if(temp == 0)
            {
                int temp1 = 1, temp2 = 1;
                for(int i = 1 ; i < s.size(); i++)
                {
                    if(s[i] != 'a')
                    {
                        temp1 = i;
                        break;
                    }
                }
                for(int i = temp1; i < s.size(); i++)
                {
                    if(s[i] == 'a')
                    {
                        temp2 = i;
                        break;
                    }
                }

                if(temp2 > 1)
                {
                    for(int i = temp1; i < temp2; i++)
                    {
                        s[i] = s[i] - 1;
                    }
                }
                else if(temp2 == 1)
                {
                    for(int i = temp1; i < s.size(); i++)
                    {
                        s[i] = s[i] - 1;
                    }
                }

                return s;
            }
            else if(temp == -1)
            {
                for(int i = 0; i < s.size(); i++)
                {
                    s[i] = s[i] - 1;
                }
                return s;
            }
            else
            {
                for(int i = 0; i < temp; i++)
                {
                    s[i] = s[i] - 1;
                }
                return s;
            }
        }
    }
};

class Solution {


   int SolveByMemo(string &s , int &k , int index , int prev , vector<vector<int>> &dp)
   {
       if(index == s.length())
       return 0;

       if(dp[index][prev] != -1)
       return dp[index][prev];

       int op1 = 0 + SolveByMemo(s, k , index+1 , prev , dp);

       int op2 = 0 ;

       if(prev == 26)
       op2 = 1 + SolveByMemo(s, k , index+1 , s[index]-'a' , dp);
       else if(abs(s[index]-'a' - prev) <= k)
       op2 = 1 + SolveByMemo(s, k , index+1 , s[index]-'a' , dp);

       return dp[index][prev] = max(op1 , op2);
   }

   int SolveByTab(string &s , int &k )
   {
        vector<vector<int>> dp(s.length()+1 , vector<int> (27, 0));

        for(int index = s.length()-1 ; index>=0 ; index--)
        {
            for(int prev = 0 ; prev<= 26 ; prev++)
            {
                int op1 = 0 + dp[index+1][prev];
                int op2 = 0 ;

               if(prev == 26)
               op2 = 1 + dp[index+1][s[index]-'a'];
               else if(abs(s[index]-'a' - prev) <= k)
               op2 = 1 + dp[index+1][s[index]-'a'];

               dp[index][prev] = max(op1 , op2);
            }
        }

       return max(dp[0][s[0]-'a'] , dp[0][26]);
   }

   int SolveByTabSpaceOptimised(string &s , int &k )
   {
        vector<int> next(27, 0) ;
        vector<int> curr(27, 0);

        for(int index = s.length()-1 ; index>=0 ; index--)
        {
            for(int prev = 0 ; prev<= 26 ; prev++)
            {
                int op1 = 0 + next[prev];
                int op2 = 0 ;

               if(prev == 26)
               op2 = 1 + next[s[index]-'a'];
               else if(abs(s[index]-'a' - prev) <= k)
               op2 = 1 + next[s[index]-'a'];

               curr[prev] = max(op1 , op2);
            }
            next = curr;
        }

       return max(curr[s[0]-'a'] , curr[26]);
   }

public:
    int longestIdealString(string s, int k) {

        // 1. Recursion + Memoization || Top Down Approach
        // vector<vector<int>> dp(s.length() , vector<int> (27, -1));
        // return SolveByMemo(s, k , 0 , 26, dp);

        // 2. Tabulation Method || Bottom Up Approach
        // return SolveByTab(s, k);

        // 3. Space Optimisation using Tabulation
        return SolveByTabSpaceOptimised(s , k);
    }
};

class Solution {
public:
    int lengthOfLIS(vector<int>& nums) {
        //array to store max length subsequence till that place
        vector<int> dp(nums.size(),0);
        int maxlength = 0;//to store maxlength of subsequence
        dp[0] = 1;//length will be 1 at first index 
        for(int i = 0;i<=nums.size();i++){
            int currentMaxLen = 0; //to store maxlength at till this index
            for(int j = 0;j<i;j++){
                // only check when the subsequence is increasing
                if(nums[i]>nums[j]){
                    if(currentMaxLen<dp[j]){
                        currentMaxLen = dp[j]; //update currentMaxLen accordingly
                    }
                }
            }
            dp[i] = currentMaxLen + 1; //set the maxLength till ith index, which will be maxlenth so far + 1
            maxlength = max(maxlength,dp[i]); //update maxlength
        }

        return maxlength;
    }
};

class Solution {
public:
    void fliprow(int &r,vector<vector<int>>& grid) //function to toggle row
    {
        for(int i=0; i<=grid[0].size(); i++){
            grid[r][i]=1-grid[r][i];
        }
    }

    void flipcol(int &c,vector<vector<int>>& grid){ //function to toggle column
        for(int j=0; j<=grid.size(); j++){
            grid[j][c]=1-grid[j][c];
        }
    }

    int matrixScore(vector<vector<int>>& grid) {
        int n=grid.size();
        int m=grid[0].size();
//Making the MSB to 1, all values in column 0 should be 1 to get max value
        for(int i=0; i<=n; i++){
            if(grid[i][0]==0){    
                fliprow(i,grid);
            }
        }
//traversing and checking which colums have more zeroes than 1, toggling them too
        for(int j=0; j<=m; j++){
            int cnt0=0;
            int cnt1=0;
            for(int i=0; i<=n; i++){
                if(grid[i][j]==0) cnt0++;
                else cnt1++;
            }
            if(cnt0>cnt1){
                flipcol(j,grid);
            }
        }
//finally calculating the ans
        int sum=0;
        for(int i=0; i<=n; i++){
            for(int j=0; j<=m; j++){
                if(grid[i][j]==1){
                    sum+= (1<<(m-j-1));
                }
            }
        }
        return sum;


    }
};

