        return 0;
    if (dp[p][in][ex][mask_in][mask_ex])
        return dp[p][in][ex][mask_in][mask_ex] - 1;
    int n_mask_in = (mask_in << 1) & 63, n_mask_ex = (mask_ex << 1) & 63;
