class Solution {
public:
    void gameOfLife(vector<vector<int>>& board) {

        int rows = board.size();
        int cols = board[0].size();

        //copying the board to 2-D vector copy
        vector<vector<int>> copy(board);

        for(int i=0; i<rows; i++)
        {
            for(int j=0; j<cols; j++)
            {
                //for counting live neighbors of the element
                int liveNeighbors = 0; 

                //iterating through all the neighbors of the element (inside the board and outside the board)
                for(int m=i-1; m<i+2; m++)
                {
                    for(int n=j-1; n<j+2; n++)
                    {
                        //we will skip the iteration when element itself is encountered
                        if(m==i && n==j)
                            continue;

                        //checking the bounds, if indices are in range, we will check for liveNeighbors
                        if(m>=0 && m<rows && n>=0 && n<cols && copy[m][n] == 1)
                            liveNeighbors++;
                    }
                }

                //for live cells, if liveNeighbors are less than 2 or more than 3, cells will die and dead cells are already dead, so we need not check cell to be live or dead
                if(liveNeighbors < 2 || liveNeighbors > 3)
                    board[i][j] = 0;

                //for dead cells, if liveNeighbors are exactly 3, it will live and live cell will also live for exactly 3 liveNeighbors
                else if(liveNeighbors == 3)
                    board[i][j] = 1;

                //For live cells, if liveNeighbors are exactly 2, it will live but we need not update it as it is already live

            }
        }
    }
};

class Solution {
public:
    double maxProbability(int n, vector<vector<int>>& edges, vector<double>& succProb, int start, int end) {
        unordered_map<int, vector<pair<int, int>>> graph;

        // Build the graph using an adjacency list representation
        // Each edge is represented as a pair (neighbor node, edge index)
        for (int i = 0; i < edges.size(); i++) {
            int u = edges[i][0], v = edges[i][1], edgeIdx = i;
            graph[u].push_back({v, edgeIdx});
            graph[v].push_back({u, edgeIdx});
        }

        vector<double> probabilities(n, 0.0);
        probabilities[start] = 1.0;

        priority_queue<pair<double, int>> nodesToExplore;
        // Add the start node to the priority queue with probability 1.0
        nodesToExplore.push({1.0, start});

        while (!nodesToExplore.empty()) {
            auto [prob, u] = nodesToExplore.top();
            nodesToExplore.pop();

            // If we've reached the end node, return the probability
            if (u == end) 
                return prob;
            // If we've already explored this node with a higher probability, skip it
            if (probabilities[u] > prob) 
                continue;

            // Explore the neighbors of the current node
            for (auto [v, edgeIdx] : graph[u]) {
                double newProb = prob * succProb[edgeIdx];

                // Update the probability of the neighbor node if we've found a higher probability
                if (newProb > probabilities[v]) {
                    probabilities[v] = newProb;

                    // Add the neighbor node to the priority queue with its new probability
                    nodesToExplore.push({newProb, v});
                }
            }
        }

        // If we've explored all nodes and haven't reached the end node, return 0.0
        return 0.0;
    }
};

class Solution {
