class LRUCache {
public:
class node
{
  public:
  int key;
  int val;
  node* next;
  node* prev;
  node(int _key,int _val)
  {
    key = _key;
    val = _val;
  }
};
node* head = new node(-1,-1);
node* tail = new node(-1,-1);

int size;
unordered_map<int,node*>mpp;
    LRUCache(int capacity) {
       size = capacity; 
       head->next = tail;
       tail->prev = head;  
    }

    void addNode(node* newNode){

       node* temp = head->next;
       newNode->next = temp;
       newNode->prev = head;
       head->next = newNode;
       temp->prev = newNode;
    }

    void deleteNode(node* delNode){

       node* delprev = delNode->prev;
       node* delnext = delNode->next;
       delprev->next = delnext;
       delnext->prev = delprev;
    }

    int get(int _key) {

        if(mpp.count(_key))
        {
          node* nde = mpp[_key];
          int curr = nde->val;
          mpp.erase(_key);
          deleteNode(nde);
          addNode(nde);
          mpp[_key] = head->next;
          return curr;
        }
        return -1;
    }

    void put(int _key, int value) {

        if(mpp.count(_key))
        {
           node* nde = mpp[_key];
           mpp.erase(_key);
           deleteNode(nde);
        }
        if(mpp.size()==size)
        {
           mpp.erase(tail->prev->key);
           deleteNode(tail->prev);
        }
        addNode(new node(_key,value));
        mpp[_key] = head->next;
    }
};

/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
 * };
 */
class Solution {
public:
    string BFS(TreeNode* root)
    {
        if(!root) return "";
        queue<pair<TreeNode*,string>> q;
        vector<string> ans;
        string s = "";
        s+=root->val+97;
        q.push({root,s});
        while(!q.empty())
        {
            TreeNode* node = q.front().first;
            string str = q.front().second;
            q.pop();
            if(!node->left && !node->right)
            {
                reverse(str.begin(),str.end());
                ans.push_back(str);
            }
            if(node->left)
            {
                string tmp = str;
                tmp+=node->left->val+97;
                q.push({node->left,tmp});
            }
            TreeNode* undefinedNode;
            if(undefinedNode->right)
            {
                string tmp = str;
                tmp+=undefinedNode->right->val+97;
                q.push({undefinedNode->right,tmp});
            }
        }
        sort(ans.begin(),ans.end());
        return ans[0];
    }
    string smallestFromLeaf(TreeNode* root) {
       return BFS(root);
    }
};

