    TreeNode* reverseOddLevels(TreeNode* root) {
        queue<TreeNode*> q;
        q.push(root);
        int x = 1,n,i,z;
        vector<TreeNode*> tmp;
        TreeNode* node;
        while(!q.empty()){
            tmp.clear();
            n = q.size();
            // cout<<n<<" ";
            while(n--){
                node = q.front();q.pop();
                // cout<<node->val<<" ";
                if(x==0){
                    tmp.push_back(node);
                }
                if(node->left)
                    q.push(node->left);
                if(node->right){
                    q.push(node->right);
                }
            }
            n = tmp.size();
            for(i = 0; i < n/2; i++){
                z = tmp[i]->val;
                tmp[i]->val = tmp[n-1-i]->val;
                tmp[n-1-i]->val = z;
            }
            x ^= 1;
            n = 0;
        }
        return root;
    }
};

class Solution {
public:
    string removeOuterParentheses(string s) {
        stack<char> st;
        string res="";
        for(int i=0;i<s.size();i++){
            if(s[i]=='(' && st.empty()){
                st.push(s[i]);
            }
            else if(s[i]=='('){
                st.push(s[i]);
                res+=s[i];
            }
            else{
                st.pop();
                if(st.size()){
                    res+=s[i];
                }
            }
        }
        return res;
    }
};

/**
 * Definition for singly-linked list.
 * struct ListNode {
 *     int val;
 *     ListNode *next;
 *     ListNode() : val(0), next(nullptr) {}
 *     ListNode(int x) : val(x), next(nullptr) {}
 *     ListNode(int x, ListNode *next) : val(x), next(next) {}
 * };
 */
class Solution {
public:
    bool flag;
    ListNode*Head;
    ListNode* undefinedObject; 
    void checkpalindrome(ListNode* Revhead){
        if(Revhead==NULL){
            return;
        }
         checkpalindrome(Revhead->next);
         if(Revhead!=NULL){
             if(Revhead->val!=undefinedObject->val){ 
                 flag=false;
             }
             Head=Head->next;
         }
    }
    bool isPalindrome(ListNode* head) {
        flag=true;
        Head=head;
        checkpalindrome(head);
        return flag;
    }
};

class Solution {
public:
   vector<int> dir = { 0, 1, 0, -1, 0 }; 
    bool isCyclic(vector<vector<char>>& grid, vector<vector<bool>>& visited, int i, int j, int x, int y)
    {
        visited[i][j] = true;
        for(int d = 0; d < 4; ++d)
        {
            int a = i+dir[d];
            int b = j+dir[d+1];
            if(a >= 0 && a < grid.size() && b >= 0 && b < grid[0].size() && grid[a][b] == grid[i][j] && !(x == a && y == b))
                if((!visited[a][b] && isCyclic(grid, visited, a,b,i,j)) || visited[a][b])
                    return true;
        }
        return false;
    }
    bool containsCycle(vector<vector<char>>& grid) {
        int n = grid.size(), m = grid[0].size();
        vector<vector<bool>> visited(n, vector<bool>(m, false));
        for(int i = 0; i < n; ++i)
            for(int j = 0; j < m; ++j)
                if(!visited[i][j] && isCyclic(grid, visited, i, j, -1, -1))
                    return true;
        return false;
    }
};

class Solution {
public:
    int find(vector<int>& inorder, int k) {
        for (int i = 0; i < inorder.size(); i++) if (inorder[i] == k) return i;
        return -1;
    }

    TreeNode* buildTree(vector<int>& preorder, vector<int>& inorder) {
        int preIndex = 0, inStart = 0, inend = inorder.size() - 1;
        return build(preorder, inorder, preIndex, inStart, inend);
    }

    TreeNode* build(vector<int>& preorder, vector<int>& inorder, int& preIndex, int inStart, int inend) {
        if (inStart > inend) {
            return NULL;
        }

        int ele = preorder[preIndex++];
        TreeNode* root = new TreeNode(ele);
        int pos_in_inorder = find(inorder, ele);

        root->left = build(preorder, inorder, preIndex, inStart, pos_in_inorder - 1);
        root->right = build(preorder, inorder, preIndex, pos_in_inorder + 1, inend);
        return root;
    }
};

import java.util.Arrays;

class Solution {
    public int[] relativeSortArray(int[] arr1, int[] arr2) {
        Arrays.sort(arr1);
        int[] ans = new int[arr1.length];
        int start = 0;
        int end = arr1.length - 1;
        int index = 0;

        for (int i = 0; i < arr2.length; i++) {
            int target = arr2[i];
            start = 0;
            end = arr1.length - 1;

            while (end >= start) {
                int mid = start + (end - start) / 2;
                if (arr1[mid] == target) {
                    for (int j = start; j <= end; j++) {
                        if (arr1[j] == target) {
                            ans[index++] = arr1[j];
                        }
                    }
                    break;
                }
                if (arr1[mid] < target) {
                    start = mid + 1;
                } else {
                    end = mid - 1;
                }
            }
        }

        for (int i = 0; i < arr1.length; i++) {
            if (index == arr1.length) {
                break;
            }
            boolean found = false;
            for (int num : arr2) {
                if (arr1[i] == num) {
                    found = true;
                    break;
                }
            }
            if (!found) {
                ans[index++] = arr1[i];
            }
        }

        return ans;
    }
}

# Definition for a binary tree node.
# class TreeNode:
#     def __init__(self, val=0, left=None, right=None):
#         self.val = val
#         self.left = left
#         self.right = right
class Solution:
    def maxProduct(self, root: Optional[TreeNode]) -> int:
        def dfs(node):
            if node:
                dfs(node.left)
                dfs(node.right)
                if node.left and node.right:
                    node.val+=node.left.val+node.right.val
                elif node.left and not node.right:
                    node.val+=node.left.val
                elif node.right:
                    node.val+=node.right.val
        dfs(root)

        ans,val=0,root.val
        def f(node):
            nonlocal ans
            if node:
                ans=max(ans,(val-node.val)*node.val)
                f(node.left)
                f(node.right)
        f(root)
        return ans%1000000007

class Solution:
    def countNegatives(self, grid: List[List[int]]) -> int:
        ROWS, COLS = len(grid), len(grid[0])
        negatives = 0
        col = 0
        for row in range(ROWS - 1, -1, -1):
            while col < COLS and grid[row][col] >= 0:
                col += 1
            negatives += COLS - col
        return negatives

class Solution {
    public int rearrangeCharacters(String s, String target) {
        int[] cnt1 = new int[26];
        int[] cnt2 = new int[26];
        for (int i = 0; i < s.length(); ++i) {
            ++cnt1[s.charAt(i) - 'a'];
        }
        for (int i = 0; i < target.length(); ++i) {
            ++cnt2[target.charAt(i) - 'a'];
        }
        int ans = 100;
        for (int i = 0; i < 26; ++i) {
            if (cnt2[i] > 0) {
                ans = Math.min(ans, cnt1[i] / cnt2[i]);
            }
        }
        return ans;
    }
}

class Solution {
    public int passThePillow(int n, int time) {
        int num=(time/(n-1));
        if(n>time){
            return time;
        }
        if(num%2==1){
            return n-((time%(n-1)));
        }

        return (time%(n-1))+1;
    }
}

