 * @return 	     -1 if num is higher than the picked number
 *			      1 if num is lower than the picked number
 *               otherwise return 0
 * int guess(int num);
 */

public class Solution extends GuessGame {
    public int guessNumber(int n) {
        int low=0,high=n;
        while(low<=high)
        {
            int mid=low+(high-low)/2;
            int x= guess(mid);
            if(x==0) 
            {
                return mid;
            }
            else if(x==-1)
            {
                high=mid-1;
            }
            else
            {
                low = mid+1;
            }
        }
        return -1;
    }
}

