class Solution {
    public boolean checkPerfectNumber(int num) {
        if(num==1){
            return false;
        }
        int sum=1;
        for(int i =2 ;i*i<=num;i++){
            if(num%i==0){
                sum+=i;
                if(i*i != num) {
                    sum += num/i;
                }
            }
        }
        if(num==sum*2){
            return true;
        }
        return false;
    }
}

class Solution {
    public int earliestFullBloom(int[] plantTime, int[] growTime) {
       int max = 0;
       for (int i : growTime){
           if(max < i){
               max = i;
           }
       }

       int len = max;
       int[] arr = new int[len + 1];
       int tmp = 0;
       int minTime = 0;

       for (int i = 0; i < plantTime.length; i++) {
           arr[growTime[i]] += plantTime[i];
       }

       for (int i = len; i > 0; i--) {
            if (arr[i] != 0) {
                tmp = tmp + arr[i];
                minTime = Math.min(minTime, tmp + i);
            }
       }

       return minTime;
    }
}

class Solution {
    public int minJumps(int[] arr) {
        Map<Integer,ArrayList<Integer>>hm=new HashMap<>();
        for(int i=0;i<arr.length;i++){
            if(hm.containsKey(arr[i])){
                ArrayList<Integer>al=hm.get(arr[i]);
                al.add(i);
                hm.put(arr[i],al);
            }
            else{
                ArrayList<Integer>al=new ArrayList<>();
                al.add(i);
                hm.put(arr[i],al);
            }
        }
        boolean vis[]=new boolean[arr.length];
        Queue<Integer>q=new LinkedList<>();
        q.add(0);
        int cnt=0;
        while(!q.isEmpty()){
            for(int k=q.size();k>0;k--){
                int n=q.remove();
                vis[n]=true;
                if(n==arr.length-1) return cnt;
                ArrayList<Integer>al=hm.get(arr[n]);
                al.add(n-1);
                al.add(n+1);
                al.clear();
                for(int i:al){
                    if(i>=0&&i<arr.length&&!vis[i]){
                        q.add(i);
                    }
                }
            }
            cnt++;
        }
        return 0;
    }
}

class Solution {
    public double new21Game(int n, int k, int maxPts) {
        if (k == 0 || n >= k + maxPts)
        return 1.0;

    double[] dp = new double[n + 1];
    double windowSum = 1.0;
    double probability = 0.0;

    dp[0] = 1.0;

    for (int i = 1; i <= n; i++) {
        dp[i] = windowSum / maxPts;

        if (i < k)
            windowSum += dp[i];
        else
            probability += dp[i];

        if (i - maxPts >= 0)
            windowSum -= dp[i - maxPts];
    }

    return probability;
    }
}

