class Solution {
    double possible = 0.0;
    double valid = 0.0;

    public double getProbability(int[] balls) {
        int[] first = new int[balls.length];
        int[] second = new int[balls.length];
        dfs(balls, first, second, 0, 0, 0);
        return valid / possible;
    }

    private void dfs(int[] balls, int[] first, int[] second, int num1, int num2, int idx) {
        // finish all colors, check if this's a possible/valid distribution
        if (idx == balls.length) {
            // find one possible distribution
            if (num1 == num2) {
                // compute fake permutation
                double distrib = permFake(first) * permFake(second);
                possible += distrib;

                // find one valid distribution
                if (unique(first) == unique(second)) {
                    valid += distrib;
                }
            }
            return;
        }

        // distribute balls in current color to two bins
        for (int b = 0; b <= balls[idx]; b++) {
            first[idx] = b;
            second[idx] = balls[idx] - b;
            dfs (balls, first, second, num1 + first[idx], num2 + second[idx], idx + 1);
        }
    }

    // unique colors in 
    private int unique(int[] balls) {
        int unique = 0;
        for (int b: balls)
            unique += b > 0 ? 1 : 0;
        return unique;
    }

    // return 1 / (b1!b2!b3!...bn!) 
    private double permFake(int[] balls) {
        double ret = 1.0;
        for (int b: balls)
            ret /= factorial(b);
        return ret;
    }

    private int factorial(int n){
        int ret = 1;
        while (n > 0) {
            ret *= n;
            n--;
        }
        return ret;
    }
}

class Solution {
    public int totalStrength(int[] strength) {
        int mod = 1000000007;

        int len = strength.length;

        long[] prefix = prefixSum(strength, len, mod);

        Deque<Integer> stack = new ArrayDeque<>();
        stack.push(-1);

        long ans = 0;
        for(int i = 0; i < len; i++) {
            while(stack.peek() != -1 && strength[i] <= strength[stack.peek()]) {
                int mid = stack.pop();
                int left = stack.peek() + 1;
                int right = i - 1;

                int n = (mid - left);
                int t = (right - mid);

                long val = (1l * (1 + n) * (prefix[right + 2] - prefix[mid + 1]) + mod) % mod;
                val -= (1l * (1 + t) * (prefix[mid + 1] - prefix[left]) + mod) % mod;
                val *= strength[mid];

                ans += val;
                ans %= mod;
            }

            stack.push(i);
        }

        int right = len - 1;
        while(stack.peek() != -1) {
            int mid = stack.pop();
            int left = stack.peek() + 1;

            int n = (mid - left);
            int t = (right - mid);

            long val = (1l * (1 + n) * (prefix[right + 2] - prefix[mid + 1]) + mod) % mod;
            val -= (1l * (1 + t) * (prefix[mid + 1] - prefix[left]) + mod) % mod;
            val *= strength[mid];

            ans += val;
            ans %= mod;
        }

        return (int)((ans + mod) % mod);
    }

    private long[] prefixSum(int[] strength, int len, int mod) {
        long[] prefix = new long[len + 1];

        for(int i = 0; i < len; i++) {
            prefix[i + 1] = prefix[i] + strength[i];
        }

        long[] doublePrefix = new long[len + 2];
        for(int i = 0; i <= len; i++) {
            doublePrefix[i + 1] = (doublePrefix[i] + prefix[i]) % mod;
        }

        return doublePrefix;
    }
}

