             return dp[i][j][diff+1000] = true;
         }

         if(j < s2.length && !Character.isDigit(s2[j]) && diff < 0 && helper(s1, s2, i, j+1, diff+1, dp)) {
             return dp[i][j][diff+1000] = true;
         }

         for(int k = i, val = 0; k < i + 4 && k < s1.length && Character.isDigit(s1[k]); k++) {
             val = val * 10 + s1[k] -'0';
             if(helper(s1, s2, i, k+1, diff-val, dp)) {
