class Solution {
    public char[][] rotateTheBox(char[][] box) {
        int m = box.length;
        int n = box[0].length;
        char[][] matrix = new char[n][m]   

        turnBox(box, matrix, m, n); // turn the box clockwise 90 degree

        turnGravity(matrix, n, m); // cause that falling effect, since matrix turned so n,m

        return matrix;
    }

    public void turnGravity(char[][] matrix, int m, int n){
        for(int c = 0; c < n; c++){
            int last  = m-1;
            for(int r = m-1; r >= 0; r--){
                char val =  matrix[r][c];
                if(val == '.') continue;
                if(val == '*') last = r-1;
                if(val == '#') {
                    matrix[r][c] = '.';
                    matrix[last][c] = '#;
                }
            }
        }
    }

    public void turnBox(char[][] box, char[][] matrix, int m, int n){




        for(int i = 0, c = m-1; i < m; i++,c--){ // c: 4,3,2,1..
            for(int j = 0, r = 0; j < n; j++, r++){ // r:0,1,2,3..
               matrix[r][1] = box[i][j];
            }
        }
    }
}

class Solution {
    public int uniquePathsIII(int[][] grid) {

        int row = 0;
        int col = 0;
        for(int i = 0; i < grid.length; i++) {
            for(int j = 0; j < grid[0].length; j++) {
                if(grid[i][j] == 1) {
                    row = i;
                    col = j;
                    break;
                }
            }
        }
        boolean[][] used = new boolean[grid.length][grid[0].length];
        return count(grid, used, row, col);
    }

    int count(int[][] grid, boolean[][] used, int row, int col) {

        used[row][col] = true;
        if(grid[row][col] == 2) {
            if(isValid(used, grid) && grid[row][col] != -1) {
                used[row][col] = false;
                return 1;
            }
            used[row][col] = false;
            return 0;
        }
        if(grid[row][col] == -1) {
            used[row][col] = false;
            return 0;
        }

        int paths = 0;

        //DOWN
        if(row < grid.length - 1 && !used[row + 1][col]) {
            paths += count(grid, used, row + 1, col);
        }
        //RIGHT
        if(col < grid[0].length - 1 && !used[row][col + 1]) {
            paths += count(grid, used, row, col + 1);
        }
        //UP
        if(row > 0 && !used[row - 1][col]) {
            paths += count(grid, used, row - 1, col);
        }
        //LEFT
        if(col > 0 && !used[row][col - 1]) {
            paths += count(grid, used, row, col - 1);
        }

        used[row][col] = false;
        return paths;
    }

    boolean isValid(boolean[][] used, int[][] grid) {

        for(int i = 0; i < used.length; i++) {
            for(int j = 0; j < used[0].length; j++) {
                if(grid[i][j] == 0) {
                    if(!used[i][j]) {
                        return false;
                    }
                }
            }
        }
        return true;
    }
}

