        if(trees.length == 3)
            return trees;
        Stack<int[]> upper = new Stack<>();
        Stack<int[]> lower = new Stack<>();

        Arrays.sort(trees,(p,q) ->q[0]-p[0]==0?q[1]-p[1]:q[0]-p[0]);

        for(int i = 0 ; i < trees.length ; i++){
