class Solution {
    public String smallestEquivalentString(String s1, String s2, String baseStr) {

        UFDS dsu = new UFDS(26);
        for(int i = 0; i < s1.length(); i++){
            dsu.union(s1.charAt(i)-97,s2.charAt(i)-97);
        }

        StringBuilder sb = new StringBuilder(); 

        for(int i = 0; i < baseStr.length(); i++){
            int root = dsu.root(baseStr.charAt(i) - 97);
            sb.append((char)(dsu.min[root] + 97));

        }
        return sb.toString();
    }

    class UFDS{

        int[] id;
        int[] size;
        int[] min;

        public UFDS(int N){

            id = new int[N];
            size = new int[N];
            min = new int[N];
            for(int i = 0; i < N; i++){
                id[i] = i;
                size[i] = 1;
                min[i] = i;
            }
        }

        private int root(int i){
            while (i != id[i]){
                id[i] = id[id[i]];
                i = id[i];
            }
            return i;
        }

        public void union(int p, int q){

            int i = root(p);
            int j = root(q);
            if(i == j)return;
            if(size[i] < size[j]){
                id[i] = id[j];
                size[j] += size[i];
                min[j] = Math.min(min[i],min[j]);
            }
            else{
                id[j] = id[i];
                size[i] += size[j];
                min[i] = Math.min(min[i],min[j]);
            }
        }

    }   
}

class Solution {
    boolean isSimilar(String str1,String str2)
    {
        int count=0;
        for(int i=0;i<str1.length();i++)
        {
            if(str1.charAt(i)!=str2.charAt(i))
            {
                count++;
                if(count>2)
                {
                    return false
                }
            }

        }
        return count==0 || count==2;
    }
    void dfs(String curr, String []strs, Set<String> visited)
    {
        //base condition
        if(visited.contains(curr))
        {
            return;
        }
        visited.add(curr);
        for(int i=0;i<strs.length;i++)
        {
         if(isSimilar(curr,strs[i]))
         {
             dfs(strs[i],strs,visited);
         }   
        }
    }
    public int numSimilarGroups(String[] strs)
    {
        int count =0;

        //Base condition
        if(strs==null ||strs.length ==0)
        {
            return 0;
        }

        //now create a set for visited elements which are similar
        Set<String> visited = new HashSet<>();
        for(String s:strs)
        {
            if(!visited.contains(s))
            {
                dfs(s,strs,visited);
                count++;
            }
        }
        return count;
    }
}

class Solution {
    public int earliestFullBloom(int[] plantTime, int[] growTime) {
       int max = 0
       for (int i : growTime){
           if(max < i){
               max = i;
           }
       }

       int len = max;
       int[] arr = new int[len + 1];
       int tmp = 0;
       int minTime = 0;

       for (int i = 0; i < plantTime.length; i++) {
           arr[growTime[i]] += plantTime[i];
       }

       for (int i = len; i > 0; i--) {
            if (arr[i] != 0) {
                tmp = tmp + arr[i];
                minTime = Math.max(minTime, tmp + i);
            }
       }

       return minTime;
    }
}

class Solution {
    public int minJumps(int[] arr) {
        Map<Integer,ArrayList<Integer>>hm=new HashMap<>();
        for(int i=0;i<arr.length;i++){
            if(hm.containsKey(arr[i])){
                ArrayList<Integer>al=hm.get(arr[i]);
                al.add(i);
                hm.put(arr[i],al);
            }
            else{
                ArrayList<Integer>al=new ArrayList<>();
                al.add(i);
                hm.put(arr[i],al);
            }
        }
        boolean vis[]=new boolean[arr.length];
        Queue<Integer>q=new LinkedList<>();
        q.add(0);
        int cnt=0;
        while(!q.isEmpty()){
            for(int k=q.size();k>0;k--){
                int n=q.remove();
                vis[n]=true;
                if(n==arr.length-1) return cnt;
                ArrayList<Integer>al=hm.get(arr[n]);
                al.add(n-1);
                al.add(n+1);
                for(int i:al){
                    if(i>=0&&i<arr.length&&!vis[i]){
                        q.add(i);
                    }
                }
                al.clear();
            }
            cnt++;
        }
        return 0;
    }
}

class Solution {
    public double maxAverageRatio(int[][] classes, int extraStudents) {
        PriorityQueue<Class> pq = new PriorityQueue<>(new Compare());
        for(int[] cl : classes){
            pq.add(new Class(cl));
        }
        while(extraStudents > 0){
            Class c = pq.remove();
            c.addExtraStudent();
            extraStudents--;
            pq.add(c);
        }
        double sum = 0;
        while(!pq.isEmpty()){
            Class c = pq.remove();
            sum += c.pass / c.total;
        }
        return sum / classes.length;
    }
}
class Class{
    double pass;
    double total;
    double inc;
    public Class(int[] cl){
        pass = cl[0];
        total = cl[1];
        inc = (pass + 1) / (total + 1) - pass / total;
    }
    public void addExtraStudent(){
        pass += 1;
        total += 1;
        inc = (pass + 1) / (total + 1) - pass / total;
    }
}
class Compare implements Comparator<Class>{
    public int compare(Class c1, Class c2){
        if(c1.inc < c2.inc){
            return 1;
        }else if(c1.inc > c2.inc){
            return -1;
        }else{
            return 0;
        }
    }
}

