        return cnt;
    }
    public int specialArray(int[] nums) {
        int maxi=Integer.MIN_VALUE,start=1,mid=0;
        for(int x:nums) maxi=Math.max(maxi,x);
        int end = maxi;
        while(start<=end){
            mid = (start+end)/2;
            int check = countPossibility(nums,mid);
            if(check==mid) return mid;
            if(mid<check) start=mid+1;
            else end=mid-1;
        }
        return -1;
    }
}

class Solution {
    int m;
    int n;
    Integer memo[][];

    public int minFallingPathSum(int[][] grid) {   
         m=grid.length;
         n=grid[0].length;
        //<<---------------for Recursive Soln--------------->>
         memo=new Integer[m][n];//memo [][]

         int recRes=Integer.MAX_VALUE;

         //iterate over the 1st rows col 
        //  for(int col=0;col<n;col++)
        //            recRes=Math.min(recRes,minFallingPathSum_Rec(grid,0,col));

      //<<---------------for Recursive Soln--------------->>
        //  return recRes;

          //<<---------------for Tabulation  Soln--------------->>
         int Tabulation_Ans=minFallingPathSum_Tabulation(grid);
         return Tabulation_Ans;
    }

    public int minFallingPathSum_Rec(int[][] grid,int i,int j){

            if(j<0 || j>=n || i<0 || i>=m)
                           return Integer.MAX_VALUE;

            if(i==m-1)
                     return grid[i][j];

            if(memo[i][j]!=null)
                        return memo[i][j];

            int lowerLeftSum=Integer.MAX_VALUE;
            int lowerRightSum=Integer.MAX_VALUE;

            for(int col=0;col<=j-1;col++)
                    lowerLeftSum=Math.min(lowerLeftSum,minFallingPathSum_Rec(grid,i+1,col));

            for(int col=j+1;col<=n-1;col++)
                    lowerRightSum=Math.min(lowerRightSum,minFallingPathSum_Rec(grid,i+1,col));

          return memo[i][j]=Math.min(lowerLeftSum,lowerRightSum)+grid[i][j];

     }//rec--->>memorization




     int minFallingPathSum_Tabulation(int[][] grid){
          int dp[][]=new int[m][n];

          for(int i=m-1;i>=0;i--){
              for(int j=n-1;j>=0;j--){

                    if(i==m-1)
                     {
                         dp[i][j]=grid[i][j];
                         continue;
                     }//base case : if the last row 

                int lowerLeftSum=Integer.MAX_VALUE;
                int lowerRightSum=Integer.MAX_VALUE;
                //for lower left sum calculation 
                for(int col=0;col<=j-1;col++){
                    lowerLeftSum=Math.min(lowerLeftSum,((col<0)?Integer.MAX_VALUE:dp[i+1][col]));
                }

                //for lower right sum calculation 
                for(int col=j+1;col<=n-1;col++){
                    lowerRightSum=Math.min(lowerRightSum,((col>=n)?Integer.MAX_VALUE:dp[i+1][col]));

                }

                dp[i][j]=Math.min(lowerLeftSum,lowerRightSum)+grid[i][j];

              }//inner 
          }//ouer 


          int Ans=Integer.MAX_VALUE;

          for(int COL=0;COL<n;COL++){
              Ans=Math.min(Ans,dp[0][COL]);
          }

          return Ans;

     }//tabulation soln:derived from the recursive soln 
}

class DisjointSet {
    int[] root;
    Long[] rank;
    DisjointSet(int size, Set<Integer> secretKeepers) {
        root = new int[size];
        rank = new Long[size];
        for (int i = 0; i < size; i++) {
            root[i] = i;
            rank[i] = secretKeepers.contains(i) ? Integer.MAX_VALUE : 1L;
        }
    }

    public int find(int vertex) {
        if(root[vertex] == vertex) return vertex;
        return root[vertex] = find(root[vertex]);
    }

    public void union(int vertex1, int vertex2) {
        int root1 = find(vertex1);
        int root2 = find(vertex2);
        if(root1 != root2) {
            if(rank[root1] > rank[root2]) {
                root[root2] = root1;
            } else if (rank[root2] > rank[root1]) {
                root[root1] = root2;
            } else {
                root[root2] = root1;
                rank[root1]++;
            }
        }
    }

    public Set<Integer> getAllSecretKeepers(Set<Integer> secretKeepers, Set<Integer> visited) {
        for (int vertex: visited) {
            if(secretKeepers.contains(find(vertex)))
                secretKeepers.add(vertex);
            else 
                root[vertex] = vertex;
        }
        return secretKeepers;
    }
}

class Solution {
    private int maxTime = Integer.MIN_VALUE;
    private int minTime = Integer.MAX_VALUE;
    public List<Integer> findAllPeople(int n, int[][] meetings, int firstPerson) {
        Set<Integer> secretKeepers = new HashSet<>(List.of(0, firstPerson));
        Map<Integer, List<Integer[]>> timeToMeetings = getTimeToMeetings(meetings);
        DisjointSet disjointSet = new DisjointSet(n, secretKeepers);
        for (int time = minTime; time <= maxTime; time++) {
            if(!timeToMeetings.containsKey(time)) continue;
            Set<Integer> visited = new HashSet<>();
            for (Integer[] meeting: timeToMeetings.get(time)) {
                int person1 = meeting[0], person2 = meeting[1];
                disjointSet.union(person1, person2);
                visited.add(person1);
                visited.add(person2);
            }
            secretKeepers = disjointSet.getAllSecretKeepers(secretKeepers, visited);
        }
        return new ArrayList<>(secretKeepers);
    }

    private Map<Integer, List<Integer[]>> getTimeToMeetings(int[][] meetings) {
        Map<Integer, List<Integer[]>> timeToMeetings = new HashMap<>();
        for (int[] meeting: meetings) {
            maxTime = Math.max(maxTime, meeting[2]);
            minTime = Math.min(minTime, meeting[2]);
            timeToMeetings.computeIfAbsent(meeting[2], e-> new ArrayList<>()).add(new Integer[]{meeting[0], meeting[1]});
        }
        return timeToMeetings;
    }
}

class LFUCache {

    final int capacity;
    int curSize;
    int minFrequency;
    Map<Integer, DLLNode> cache;
    Map<Integer, DoubleLinkedList> frequencyMap;

    /*.*/
    /*
    * @param capacity: total capacity of LFU Cache
    * @param curSize: current size of LFU cache
    * @param minFrequency: frequency of the last linked list (the minimum frequency of entire LFU cache)
    * @param cache: a hash map that has key to Node mapping, which used for storing all nodes by their keys
    * @param frequencyMap: a hash map that has key to linked list mapping, which used for storing all
    * double linked list by their frequencies
    * */
    public LFUCache(int capacity) {
        this.capacity = capacity;
        this.curSize = 0;
        this.minFrequency = 0;

        this.cache = new HashMap<>();
        this.frequencyMap = new HashMap<>();
    }

    /** get node value by key, and then update node frequency as well as relocate that node **/
    public int get(int key) {
        DLLNode curNode = cache.get(key);
        if (curNode == null) {
            return -1;
        }
        updateNode(curNode);
        return curNode.val;
    }

    /**
     * add new node into LFU cache, as well as double linked list
     * condition 1: if LFU cache has input key, update node value and node position in list
     * condition 2: if LFU cache does NOT have input key
     *  - sub condition 1: if LFU cache does NOT have enough space, remove the Least Recent Used node
     *  in minimum frequency list, then add new node
     *  - sub condition 2: if LFU cache has enough space, add new node directly
     * **/
    public void put(int key, int value) {
        // corner case: check cache capacity initialization
        if (capacity == 0) {
            return;
        }

        if (cache.containsKey(key)) {
            DLLNode curNode = cache.get(key);
            curNode.val = value;
            updateNode(curNode);
        }
        else {
            curSize++;
            if (curSize > capacity) {
                // get minimum frequency list
                DoubleLinkedList minFreqList = frequencyMap.get(minFrequency);
                cache.remove(minFreqList.tail.prev.key);
                minFreqList.removeNode(minFreqList.tail.prev);
                curSize--;
            }
            // reset min frequency to 1 because of adding new node
            minFrequency = 1;
            DLLNode newNode = new DLLNode(key, value);

            // get the list with frequency 1, and then add new node into the list, as well as into LFU cache
            DoubleLinkedList curList = frequencyMap.getOrDefault(1, new DoubleLinkedList());
            curList.addNode(newNode);
            frequencyMap.put(1, curList);
            cache.put(key, newNode);
        }
    }

    public void updateNode(DLLNode curNode) {
        int curFreq = curNode.frequency;
        DoubleLinkedList curList = frequencyMap.get(curFreq);
        curList.removeNode(curNode);

        // if current list the the last list which has lowest frequency and current node is the only node in that list
        // we need to remove the entire list and then increase min frequency value by 1
        if (curFreq == minFrequency && curList.listSize == 0) {
            minFrequency++;
        }

        curNode.frequency++;
        // add current node to another list has current frequency + 1,
        // if we do not have the list with this frequency, initialize it
        DoubleLinkedList newList = frequencyMap.getOrDefault(curNode.frequency, new DoubleLinkedList());
        newList.addNode(curNode);
        frequencyMap.put(curNode.frequency, newList);
    }

    /*
    * @param key: node key
    * @param val: node value
    * @param frequency: frequency count of current node
    * (all nodes connected in same double linked list has same frequency)
    * @param prev: previous pointer of current node
    * @param next: next pointer of current node
    * */
    class DLLNode {
        int key;
        int val;
        int frequency;
        DLLNode prev;
        DLLNode next;

        public DLLNode(int key, int val) {
            this.key = key;
            this.val = val;
            this.frequency = 1;
        }
    }

    /*
    * @param listSize: current size of double linked list
    * @param head: head node of double linked list
    * @param tail: tail node of double linked list
    * */
    class DoubleLinkedList {
        int listSize;
        DLLNode head;
        DLLNode tail;
        public DoubleLinkedList() {
            this.listSize = 0;
            this.head = new DLLNode(0, 0);
            this.tail = new DLLNode(0, 0);
            head.next = tail;
            tail.prev = head;
        }

        /** add new node into head of list and increase list size by 1 **/
        public void addNode(DLLNode curNode) {
            DLLNode nextNode = head.next;
            curNode.next = nextNode;
            curNode.prev = head;
            head.next = curNode;
            nextNode.prev = curNode;
            listSize++;
        }

        /** remove input node and decrease list size by 1**/
        public void removeNode(DLLNode curNode) {
            DLLNode prevNode = curNode.prev;
            DLLNode nextNode = curNode.next;
            prevNode.next = nextNode;
            nextNode.prev = prevNode;
            listSize--;
        }

    }
}

