class Solution {
    public char[][] rotateTheBox(char[][] box) {
        int m = box.length;
        int n = box[0].length;
        char[][] matrix = new char[n][m];   

        turnBox(box, matrix, m, n); // turn the box clockwise 90 degree

        turnGravity(matrix, n, m); // cause that falling effect, since matrix turned so n,m

        return matrix;
    }

    public void turnGravity(char[][] matrix, int m, int n){
        for(int c = 0; c < n; c++){
            int last  = m-1;
            for(int r = m-1; r >= 0; r--){
                char val =  matrix[r][c];
                if(val == '.') continue;
                if(val == '*') last = r-1;
                if(val == '#') {
                    matrix[r][c] = '.';
                    matrix[last][c] = '#';
                    last--;
                }
            }
        }
    }

    public void turnBox(char[][] box, char[][] matrix, int m, int n){
	// numbers represents sequence it would be copied
	//[4][1]
	//[5][2]
	//[6][3]
        for(int i = 0, c = m-1; i < m; i++,c--){ // c: 4,3,2,1..
            for(int j = 0, r = 0; j < n; j++, r++){ // r:0,1,2,3..
               matrix[r][c] = box[i][j];
            }
        }
    }
}

class Solution {
    int[][] dp;
    public int minScoreTriangulation(int[] values) {
        int l=values.length;
        dp = new int[l][l];
        for int[] i : dp) Arrays.fill(i,-1);
        return solve(values,1,l-1); 
    }

    public int solve(int[] values, int i,int j)
    {
        if(i>=j) return 0;
        if(dp[i][j]!=-1) return dp[i][j];
        int min=Integer.MAX_VALUE;
        for(int k=i;k<j;k++)
        {
            int temp=solve(values,i,k)+solve(values,k+1,j)+
                        values[i-1]*values[k]*values[j];
            min=Math.min(min,temp);
        }

        return dp[i][j]=min;
    }
}

