class Solution {
    public int maxCount(int[] banned, int n, int maxSum) {

        // Create a HashSet of banned integers for fast lookup
        Set<Integer> banSet = new HashSet<>();
        for (int num : banned) {
            banSet.add(num);
        }

        // Initialize count and sum to 0
        int count = 0;
        int sum = 0;

        // Iterate over the range [1, n]
        for (int i = 1; i <= n; i++) {

            // Check if the current integer is not banned and adding it to sum does not exceed maxSum
            if (!banSet.contains(i) && (sum + i <= maxSum)) {
            // Increment count and add the current integer to sum
                count++;
                sum += i;
            }
        }
    // Return the maximum count of chosen integers
    return count;
    }
}

class Solution {
    Map<String, Integer> res = new TreeMap<>();
    Stack<Integer> stack = new Stack<>();
    int multiplier = 1;

    public String countOfAtoms(String formula) {
        int end = formula.length() - 1, i = formula.length() - 1;

        while (i >= 0) {
            if (formula.charAt(i) == '(') {
                multiplier /= stack.pop();
                i--;
                continue;
            }

            end = i;
            int val = 1;

            if (Character.isDigit(formula.charAt(i))) {
                while (Character.isDigit(formula.charAt(i))) i--;
                val = Integer.parseInt(formula.substring(i+1, end+1));
            } 
            stack.push(val);
            multiplier *= val;

            end = i;
            if (Character.isLetter(formula.charAt(i))) {
                while(Character.isLowerCase(formula.charAt(i))) i--;
                updateMap(formula.substring(i, end+1));
            }
            i--;
        }

        StringBuilder rs = new StringBuilder();
        for (Map.Entry<String, Integer> entry : res.entrySet()) {
            rs.append(entry.getKey());
            if (entry.getValue() > 1) rs.append(entry.getValue());
        }
        return rs.toString();
    }

    private void updateMap(String key) {
        if (res.get(key) == null) {
            res.put(key, multiplier);
        } else {
            res.put(key, multiplier + res.get(key));
        }

        multiplier /= stack.pop();
    }
}

