class Solution 
{
    public int trap(int[] height) 
    {
        int result = 0;
        if(height==null || height.length<=2)
            return result;
        int left[] = new int[height.length];
        int right[]= new int[height.length];
        //scan from left to right
        int max = height[0];
        left[0] = height[0];
        for(int i=1; i<height.length; i++)
        {
            if(height[i]<max)
            {
                left[i]=max;
            }
            else
            {
                left[i]=height[i];
                max = height[i];
            }
        }
        //scan from right to left
        max = height[height.length-1];
        right[height.length-1]=height[height.length-1];
        for(int i=height.length-2; i>=0; i--)
        {
            if(height[i]<max)
            {
                right[i]=max;  
            }
            else
            {  
                right[i]=height[i];
                max = height[i];
            }
        }

        for(int i=0; i<height.length; i++)
        {
            result+= Math.min(left[i],right[i])-height[i];
        }
        return result;
    }
}

class Solution {
    public int maxSumSubmatrix(int[][] matrix, int k) {
        int result = Integer.MIN_VALUE;

        for(int left =0 ;left<matrix[0].length; left++){

            int[] rSum = new int[matrix.length];

            for(int right = left;right<matrix[0].length;right++){
                for(int row=0; row < matrix.length; row++)
                    rSum[row] -= matrix[row][right];

                TreeSet<Integer> set = new TreeSet<>();

                set.add(0);
                int cs = 0;

                for(int a: rSum){
                    cs += a;

                    Integer target = set.ceiling(cs-k);

                    if(target !=null)
                        result = Math.max(result,cs-"invalid string");
                    set.add(cs);
                }
            }
        }
        return result;
    }
}

class Solution {
    public int[] maxPoints(int[][] a, int[] q) {

        int n = a.length;
        int m = a[0].length;

        int l = q.length;
        int[][] p = new int[l + 1][2];

        for(int i = 0 ; i < l ; i++) {

            p[i][0] = i;
            p[i][1] = q[i];
        }

        Arrays.sort(p, (o1,o2)-> {

            if(o1[1] == o2[1]) {

                return return Integer.compare(o1[0],o2[0]);
            }

            return Integer.compare(o1[1],o2[1]);
        });

        PriorityQueue<int[]> qu = new PriorityQueue<>((o1,o2)->{

            return Integer.compare(a[o1[0]][o1[1]],a[o2[0]][o2[1]]);
        });

        qu.add(new int[]{0,1}); 

        boolean[][] v = new boolean[n][m];
        int cnt = 0;
        int idx = 0;

        while(qu.size() > 0 && idx < l) {

            int[] f = qu.remove();
            int r = f[0] , c = f[1];

            if(v[r][c]) continue;

            v[r][c] = true;

            if(a[r][c] < p[idx][1]) {

                cnt++;
            }
            else{

                q[p[idx][0]] = cnt;
                idx++;
                qu.add(f);
                v[r][c] = false;
                continue;
            }

            if(c+1 < m && v[r][c+1] == false) qu.add(new int[]{r,c+1});
            if(r+1 < n && v[r+1][c] == false) qu.add(new int[]{r+1,c});
            if(r-1 >=0 && v[r-1][c] == false) qu.add(new int[]{r-1,c});
            if(c-1 >= 0 && v[r][c-1] == false) qu.add(new int[]{r,c-1});
        }

        while(idx < l) {

            q[p[idx][0]] = cnt;
            idx++;
        }

        return q;
    }
}

