class Solution {
    /** Algorithm
        1. If nr of columns or rows < 3 return false 
        2. Traverse the grid with i, j from 0 to row -2, col -2 and count how many magic squares/views exist.
        3. For each such view (3x3), determine if it satisfies the listen conditions:
           - use a boolean[10] seen to mark the already present number in 3x3 view
           - return false if number if <1 or > 9
           - return false if any found sum is different that a reference sum
        4. Count the views /3x3 matrices and return their number   
    */
    public int numMagicSquaresInside(int[][] grid) {
        if(grid.length < 3 || grid[0].length < 3) {
            return 0;
        }
        int magicSquares = 0;
        for (int i = 0; i < grid.length -2; i++) {
            for (int j = 0; j < grid[i].length -2; j++) {
                if (isMagicSquare(grid, i, j)) {
                    magicSquares++;
                }
            }
        }
        return magicSquares;
    }

    private boolean isMagicSquare(int[][] grid, int row, int col) {
        // map the present number is a boolean of 10 (1-9)
        boolean[] seen = new boolean[10];
        // calculate a reference sum, the sum of first row than has to match with the rest of 7 sums
        int sum = grid[row][col] + grid[row][col+1] + grid[row][col+2];
        int tempSum = 0;
        // row sum
        for (int i = row; i <= row +2; i++) {
            tempSum = 0;
            for (int j = col; j <= col +2; j++) {
                // if nr if < 9 or > 9 OR already exists, return immediately false as this 3x3 grid is not magic
                if (grid[i][j] > 9 || grid[i][j] < 1 || seen[grid[i][j]]) {
                    return false;
                }
                seen[grid[i][j]] = true;
                tempSum += grid[i][j];
            }
            if (tempSum != sum) {
                return false;
            }
        }
        //col sum
        for (int j = col; j <= col +2; j++) {
            if (grid[row][j] + grid[row +1][j] + grid[row+2][j] != sum) {
                return false;
            }
        }
        //diag 1 and 2
        if (grid[row][col] + grid[row+1][col+1] + grid[row+2][col+2] != sum ||
           grid[row][col+2] + grid[row+1][col+1] + grid[row+2][col] != sum) {
            return false;
        }
        return true;
    }
}

/**
 * Definition for a binary tree node.
 * public class TreeNode {
 *     int val;
 *     TreeNode left;
 *     TreeNode right;
 *     TreeNode() {}
 *     TreeNode(int val) { this.val = val; }
 *     TreeNode(int val, TreeNode left, TreeNode right) {
 *         this.val = val;
 *         this.left = left;
 *         this.right = right;
 *     }
 * }
 */
class Solution {
    int index;
    public TreeNode buildTree(int[] inorder, int[] postorder) {
        Map<Integer, Integer> m = new HashMap<>();

        for(int i = 0; i < inorder.length; i++) {
            m.put(inorder[i], i);
        }
        index = postorder.length - 1;
        return buildTree(0, postorder.length - 1, postorder, m);
    }

    private TreeNode buildTree(int l, int r, int postorder[] , Map<Integer, Integer> m) {
        if(l > r) return null;

        int val = postorder[index];
        index--;

        TreeNode root = new TreeNode(val);
        if(l == r) return root;

        int in = m.get(val);

        root.right = buildTree(in + 1, r, postorder, m);
        root.left = buildTree(l, in - 1, postorder, m);

        return root;
    }
}

class Solution {
    public int[] sortEvenOdd(int[] nums) {
        int n = nums.length;
        int[] even = new int[(n + 1) / 2];
        int[] odd = new int[n / 2];
        int iE = 0;
        int iO = 0;

        for(int i = 0; i < n; i++) {
            if(i % 2 == 0) {
                even[iE++] = nums[i];
            } else {
                odd[iO++] = nums[i];
            }
        }

        Arrays.sort(even);
        Arrays.sort(odd);
        iE = 0;
        iO = n / 2 - 1;

        for(int i = 0; i < n; i++) {
            if(i % 2 == 0) {
                nums[i] = even[iE++];
            } else {
                nums[i] = odd[iO--];
            }
        }

        return nums;
    }
}

class Solution {
    double possible = 0.0;
    double valid = 0.0;

    public double getProbability(int[] balls) {
        int[] first = new int[balls.length];
        int[] second = new int[balls.length];
        dfs(balls, first, second, 0, 0, 0);
        return valid / possible;
    }

    private void dfs(int[] balls, int[] first, int[] second, int num1, int num2, int idx) {
        // finish all colors, check if this's a possible/valid distribution
        if (idx == balls.length) {
            // find one possible distribution
            if (num1 == num2) {
                // compute fake permutation
                double distrib = permFake(first) * permFake(second);
                possible += distrib;

                // find one valid distribution
                if (unique(first) == unique(second)) {
                    valid += distrib;
                }
            }
            return;
        }

        // distribute balls in current color to two bins
        for (int b = 0; b <= balls[idx]; b++) {
            first[idx] = b;
            second[idx] = balls[idx] - b;
            dfs (balls, first, second, num1 + first[idx], num2 + second[idx], idx + 1);
        }
    }

    // unique colors in 
    private int unique(int[] balls) {
        int unique = 0;
        for (int b: balls)
            unique += b > 0 ? 1 : 0;
        return unique;
    }

    // return 1 / (b1!b2!b3!...bn!) 
    private double permFake(int[] balls) {
        double ret = 1.0;
        for (int b: balls)
            ret /= factorial(b);
        return ret;
    }

    private int factorial(int n){
        int ret = 1;
        while (n > 0) {
            ret *= n;
            n--;
        }
        return ret;
    }
}

