class Solution {
    public int calPoints(String[] operations) {

        Stack<Integer> stack = new Stack<>();

        for(int i=0; i<operations.length; i++){
            if(operations[i].equals("C")){
                stack.pop();
            }else if(operations[i].equals("D")){
                stack.push(stack.peek() * 2);
            }else if(operations[i].equals("+") && stack.size()>=2){
                int value1 = stack.pop();
                int value2 = stack.pop();
                int value = value1+ value2;
                //push value2 back to the stack frist
                stack.push(value2);
                stack.push(value1);
                stack.push(value);
            }else {
                stack.push(Integer.parseInt(operations[i]));
            }
        }

        System.out.println("Stack" + stack);

        int sum =0;
        while (!stack.isEmpty()){
            sum += stack.pop();
        }

        return sum;
    }
}

class Solution {
    public int diagonalPrime(int[][] nums) {
        int n = nums.length;
        int m = nums[0].length;
        int maxim = 0;
        for (int i = 0; i <= n; i++) {
                if (checkPrime(nums[i][i])) {
                    maxim = Math.max(maxim, nums[i][i]);
                } 
                if (checkPrime(nums[n-1-i][i])) {
                    maxim = Math.max(maxim, nums[n - i - 1][i]);
                }
        return maxim;
        }
    }
    public boolean checkPrime(int k) {
        int count = 0;
        if (k == 1) {
            return false;
        }
        for (int i = 1; i * i <= k; i++) {
          if (k % i == 0) {
              count += 2;
          }
      }
      if (count == 2) {
          return true; 
      } else {
          return false;
      }

    }
}

