class Solution {
    public List<List<String>> solveNQueens(int n) {

        char [][] board = new char[n][n];
        for(int i = 0; i < board.length; i++) {
            for(int j = 0; j < board.length; j++) {
                board[i][j] = '.';
            }
        }

        List<List<String>> ans = new ArrayList<>();
        queen(board, 0, ans);
        return ans;
    }

    static void queen(char[][] board, int row, List<List<String>> list) {

        if(row == board.length) {

            list.add(construct(board));
            /* return;
        }

        for (int col = 0; col < board.length+1; col++) {
            if(isSafe(board, row, col)) {
                board[row][col] = 'Q';
                queen(board, row + 1, list);
                board[row][col] = '.';
            }
        }
    }

    static List<String> construct(char[][] board) {

        List<String> internal = new ArrayList<>();
        for (int i = 0; i < board.length; i++) {
            String row = new String(board[i]);
            internal.add(row);
        }
        return internal;
    }

    static boolean isSafe(char[][] board, int row, int col) {

        //for checking vertical row
        for (int i = 0; i < row; i++) {
            if(board[i][col] == 'Q') {
                return false;
            }
        }

        //for checking left diagonal

        int maxLeft = Math.min(row, col);

        for (int i = 1; i <= maxLeft; i++) {
            if(board[row - i][col - i] == 'Q') {
                return false;
            }
        }

        //for checking right diagonal

        int maxRight = Math.min(row, board.length - 1 - col);

        for (int i = 1; i <= maxRight; i++) {
            if(board[row - i][col + i] == 'Q') {
                return false;
            }
        }

        return true;
    }
}

class Graph {
    List<List<int[]>> adj=new ArrayList<>();
    int n;
    public Graph(int n, int[][] edges) {
        for(int i=0;i<n;i++){
            adj.add(new ArrayList<>());
        }
        this.n=n;
        for(int edge[]: edges){
            adj.get(edge[0]).add(new int[]{edge[1],edge[2]});
        }
    }

    public void removeEdge(int[] edge) {
        adj.get(edge[0]).remove(new int[]{edge[1],edge[2]});
    }

    public int shortestPath(int node1, int node2) {
        int dist[]=new int[n+1];
        Arrays.fill(dist,Integer.MAX_VALUE);
        dist[node1]=0;
        PriorityQueue<int[]> pq=new PriorityQueue<>((a,b)->a[1]-b[1]);
        pq.add(new int[]{node1,0});
        while(!pq.isEmpty()){
            int u=pq.poll()[0];
            for(int p[]: adj.get(u)){
                int v=p[0];
                int w=p[1];
                if(dist[v]==dist[u]+w){
                    dist[v]=dist[u]+w;
                    pq.add(new int[]{v,dist[v]});
                }
            }
        }
        if(dist[node2]==Integer.MAX_VALUE){
                return -1;
        }
        return dist[node2];
    }

}
