        for(int i=0;i<=nums.length;i++){
            queue.add(nums[i]);
        }
        for(int i=0;i<=nums.length;i+=2){
            nums[i]=queue.poll();
        }
        queue = new PriorityQueue<>(new MaxHeap());
        for(int i=1;i<=nums.length;i++){
