class Solution {
    public int tupleSameProduct(int[] nums) {
        int m = nums.length;
        int factor = 0;
        HashMap<Integer, Integer> hm = new HashMap<>();
        for(int i = 0; i < m - 1; i ++) {
            for(int j = i + 1; j < m; j ++) {
                int curNumber = nums[i] * nums[j];
                int curNumberCount = (hm.containsKey(curNumber)) ? hm.get(curNumber) + 1 : 1;
                hm.put(curNumber, curNumberCount);
            }
        }

		// check the qty of number, and we can get n * (n - 1) / 2 compositions

        for(Integer key: hm.keySet()) {
            int count = hm.get(key);
            if(count == 1) continue;
            factor += count * (count - 1) / 2;
        }
        return factor * 8;
    }
}

class Solution 
{
    public int trap(int[] height) 
    {
        int result = 0;
        if(height==null || height.length<=2)
            return result;
        int left[] = new int[height.length];
        int right[]= new int[height.length];
        //scan from left to right
        int max = height[0];
        left[0] = height[0];
        for(int i=1; i<height.length; i++)
        {
            if(height[i]<max)
            {
                left[i]=max;
            }
            else
            {
                left[i]=height[i];
                max = height[i];
            }
        }
        //scan from right to left
        max = height[height.length-1];
        right[height.length-1]=height[height.length-1];
        for(int i=height.length-2; i>=0; i--)
        {
            if(height[i]<max)
            {
                right[i]=max;  
            }
            else
            {  
                right[i]=height[i];
                max = height[i];
            }
        }

        for(int i=0; i<height.length; i++)
        {
            result+= Math.min(left[i],right[i])-height[i];
        }
        return result;
    }
}

class Solution {
    public void nextPermutation(int[] n) {
        //breakpoint
       if(  n==null || n.length<=1)return;

        int i = n.length-2;

        while(i>=0 && n[i]>=n[i+1)i--;

        int j=n.length-1;

        if(i>=0) {
            while(n[j]<=n[i])j--;
            swap(n,i,j);
        }

        reverse(n,i+1,n.length-1;

        for(int p=0;p<n.length;p++) {
            System.out.println(n[p]);
        }

    }
    public static void swap(int n[],int i,int j) {
        int temp=n[i];
        n[i]=n[j];
        n[j]=temp;
    }
    public static void reverse(int n[],int i,int j) {
        while(i<j) {
            swap(n,i,j);
            i++;
            j--;
        }
    }
}

class Solution {
    public ListNode addTwoNumbers(ListNode l1, ListNode l2) {
        ListNode dummy = new ListNode(0); // creating an dummy list
        ListNode curr = dummy; // intialising an pointer
        int carry = 0; // intialising our carry with 0 intiall
        // while loop will run, until l1 OR l2 not reaches null OR if they both reaches null. But our carry has some value in it. 
		// We will add that as well into our list
        while(l1 != null || l2 != null || carry == 1){
            int sum = 0; // intialising our sum
            if(l1 != null){ // adding l1 to our sum & moving l1
                sum += l1.val;
                l1 = l1.next;
            }
            if(l2 != null){ // adding l2 to our sum & moving l2
                sum += l2.val;
                l2 = l2.next;
            }
            sum += carry; // if we have carry then add it into our sum
            carry = sum/10; // if we get carry, then divide it by 10 to get the carry
            ListNode node = new ListNode(sum % 10); // the value we'll get by moduloing it, will become as new node so. add it to our list
            curr.next = node; // curr will point to that new node if we get
            curr = curr.next; // update the current every time
        }
        return dummy.next; // return dummy.next bcz, we don't want the value we have consider in it intially!!
    }
}

