        for(int i=0;i<s.length();i++){
            int num = str.indexOf((s.charAt(i))); 
            arr[++num]=arr[num]+1;
        }

        int len = s.length();
        int count=0;
        StringBuilder ans = new StringBuilder();

        while(count<len){
            for(int i=1;i<27;i++){
                if(arr[i]>0){
                    ans.append(str.charAt(i - 1)); 
                    arr[i]=arr[i]-1;
