        mat=[[-1 for i in range(n)] for i in range(m)]
        temp=head
        d=1
        rowi,colj=0,0
        while temp!=None:
            mat[rowi][colj]=temp.val
            if d==1:
                if colj+1<n and mat[rowi][colj+1]==-1:
                    colj+=1
                    d=1
                elif rowi+1<m and mat[rowi+1][colj]==-1:
                    rowi+=1
