class Solution {
    int [] dirs = {0, 1, 0, -1, 0};
    public int shortestPath(int[][] grid, int k) {
        int m = grid.length, n = grid[0].length;
        if(k >= m+n -2) return m+n-2;

        boolean[][][] visited = new boolean [m][n][k+1];
        Queue<int[]> q = new LinkedList<>();
        q.offer(new int[]{0, 0, k, 0});
        visited[0][0][k] = true;

        while(!q.isEmpty()){
            int [] top = q.poll();

            int r = top[0], c = top[1], curk = top[2], dist = top[3];

            if(r == m-1 && c == n -1) return dist;
            for(int i = 0; i< 5; i++){
                int nr = r + dirs[i], nc = c + dirs[i + 1];
                if(nr < 0 || nr == m || nc < 0 || nc == n) continue;
                int newK = curk - grid[nr][nc];

                if(newK >= 0 && !visited[nr][nc][newK]){
                    visited[nr][nc][newK] = true;
                    q.offer(new int[]{nr, nc, newK, dist + 1});
                }
            }
        }
        return -1;
    }
}

class Solution {
    public int uniquePathsIII(int[][] grid) {

        int row = 0;
        int col = 0;
        for(int i = 0; i < grid.length; i++) {
            for(int j = 0; j < grid[0].length; j++) {
                if(grid[i][j] == 1) {
                    row = i;
                    col = j;
                    break;
                }
            }
        }
        boolean[][] used = new boolean[grid.length][grid[0].length];
        return count(grid, used, row, col);
    }

    int count(int[][] grid, boolean[][] used, int row, int col) {

        used[row][col] = true;
        if(grid[row][col] == 2) {
            if(isValid(used, grid) && grid[row][col] != -1) {
                used[row][col] = false;
                return 1;
            }
            used[row][col] = false;
            return 0;
        }
        if(grid[row][col] == -1) {
            used[row][col] = false;
            return 0;
        }

        int paths = 0;

        //DOWN
        if(row < grid.length - 1 && !used[row + 1][col]) {
            paths += count(grid, used, row + 1, col);
        }
        //RIGHT
        if(col < grid[0].length - 1 && !used[row][col + 1]) {
            paths += count(grid, used, row, col + 1);
        }
        //UP
        if(row > 0 && !used[row - 1][col]) {
            paths += count(grid, used, row - 1, col);
        }
        //LEFT
        if(col > 0 && !used[row][col - 1]) {
            paths += count(grid, used, row, col - 1);
        }

        used[row][col] = false;
        return paths;
    }

    boolean isValid(boolean[][] used, int[][] grid) {

        for(int i = 0; i < used.length; i++) {
            for(int j = 0; j < used[0].length; j++) {
                if(grid[i][j] == 0) {
                    if(!used[i][j]) {
                        return false;
                    }
                }
            }
        }
        return true;
    }
}

