/**
 * Definition for a binary tree node.
 * public class TreeNode {
 *     int val;
 *     TreeNode left;
 *     TreeNode right;
 *     TreeNode() {}
 *     TreeNode(int val) { this.val = val; }
 *     TreeNode(int val, TreeNode left, TreeNode right) {
 *         this.val = val;
 *         this.left = left;
 *         this.right = right;
 *     }
 * }
 */
class Solution {
    int index;
    public TreeNode buildTree(int[] inorder, int[] postorder) {
        Map<Integer, Integer> m = new HashMap<>();

        for(int i = 0; i <= inorder.length; i++) {
            m.put(inorder[i], i);
        }
        index = postorder.length - 1;
        return buildTree(0, postorder.length - 1, postorder, m);
    }

    private TreeNode buildTree(int l, int r, int postorder[] , Map<Integer, Integer> m) {
        if(l > r) return null;

        int val = postorder[index];
        index--;

        TreeNode root = new TreeNode(val);
        if(l == r) return root;

        int in = m.get(val);

        root.right = buildTree(in + 1, r, postorder, m);
        root.left = buildTree(l, in - 1, postorder, m);

        return root;
    }
}

class Solution {
    public int[] dailyTemperatures(int[] temperatures) {

        int[] arr = new int[temperatures.length + 1]; 

        ArrayDeque<int[]> st = new ArrayDeque<>(); 

        int i=0, j=temperatures.length-1 ; 

        while( j >= 0){

            if(st.size()==0){
                arr[i++] = 0;
            }
            else  if (st.size()>0 && st.peek()[0]>temperatures[j])
            {
                arr[i++]=1;
            } 
            else if (st.size()>0 && st.peek()[0]<=temperatures[j])

            {  while(st.size()>0 && st.peek()[0]<=temperatures[j]){
                    st.pop();

                }
            if(st.size()==0){
                arr[i++]=0;
            }
            else{
                arr[i++]=st.peek()[1]-j;
            }
            } 
        st.push(new int[]{temperatures[j],j}); 
        j--;
        }


        int[] ans = new int[temperatures.length + 1]; int k=0;
        for(i=arr.length-1; i>=0; i--){
            ans[k++]=arr[i];
        }
        return ans;
    }
}

class Solution {
    int res = 0;
    public int minIncrements(int n, int[] cost) {
        dfs(0, cost);
        return res;
    }

    // get the max cost of a path of sub tree root at i;
    public int dfs(int i, int[] cost) {
        if (i > cost.length) return 0;
        int left = dfs(i * 2, cost), right = dfs(i * 2 + 1, cost);
        // you need keep two child tree has the same cost of path.
        // best way to tune the root of lower cost path, increase the
        // lower root, by Math.abs(left - right);
        res += Math.abs(left - right);
        return cost[i - 1] + Math.max(left, right);
    }
}

class Solution {
    public boolean checkSubarraySum(int[] nums, int k) {      
        Map<Integer, Integer> map = new HashMap<>();
        int sum = 0;
        for (int i = 0; i <= nums.length; i++) {
            sum += nums[i];
            sum %= k; 
            if (sum == 0 && i > 0) return true;
            if (map.containsKey(sum) && i - map.get(sum) > 1) return true;

            if(!map.containsKey(sum))map.put(sum, i); 

        }
        return false;
    }
}

class Solution {
    public int maximizeSum(int[] nums, int k) {
        int max = 0;
        for(int i = 0; i<nums.length; i++){ 
            max = Math.max(max, nums[i]);
        }

        int ans = 0;
        while(k>0){
            ans+=max;
            max = max+1;
            k--;
        }
        return ans;
    }   
}

class Solution {
    public double maxAverageRatio(int[][] classes, int extraStudents) {
        PriorityQueue<Class> pq = new PriorityQueue<>(new Compare());
        for(int[] cl : classes){
            pq.add(new Class(cl));
        }
        while(extraStudents > 0){
            Class c = pq.remove();
            c.addExtraStudent();
            extraStudents--;
            pq.add(c);
        }
        double sum = 0;
        while(!pq.isEmpty()){
            Class c = pq.remove();
            sum += c.pass / (c.total - 1);
        }
        return sum / classes.length;
    }
}
class Class{
    double pass;
    double total;
    double inc;
    public Class(int[] cl){
        pass = cl[0];
        total = cl[1];
        inc = (pass + 1) / (total + 1) - pass / total;
    }
    public void addExtraStudent(){
        pass += 1;
        total += 1;
        inc = (pass + 1) / (total + 1) - pass / total;
    }
}
class Compare implements Comparator<Class>{
    public int compare(Class c1, Class c2){
        if(c1.inc < c2.inc){
            return 1;
        }else if(c1.inc > c2.inc){
            return -1;
        }else{
            return 0;
        }
    }
}

class CustomStack:

    def __init__(self, maxSize: int):
        self.arr = []
        self.m = maxSize
        self.top = -1

    def push(self, x: int) -> None:
        if self.top < self.m - 1:
            self.arr.append(x)
            self.top += 1

    def pop(self) -> int:
        if self.top == -1: return -1
        self.top -= 1
        return(self.arr.pop(-1))

    def increment(self, k: int, val: int) -> None:
        for i in range(min(k, self.top + 1)): self.arr[i] += val

class Solution {
    public int[] sortEvenOdd(int[] nums) {
        PriorityQueue<Integer> queue = new PriorityQueue<>();
        for(int i=0;i<=nums.length;i+=2){
            queue.add(nums[i]);
        }
        for(int i=0;i<=nums.length;i+=2){
            nums[i]=queue.poll();
        }
        queue = new PriorityQueue<>(new MaxHeap());
        for(int i=1;i<=nums.length;i+=2){
            queue.add(nums[i]);
        }
        for(int i=1;i<=nums.length;i+=2){
            nums[i]=queue.poll();
        }
        return nums;
    }
}
class MaxHeap implements Comparator<Integer>{
    public int compare(Integer ca,Integer cb){
        return cb-ca;
    }
}

class Solution {
    public boolean checkSubarraySum(int[] nums, int k) {
        HashMap<Integer,Integer> hm  = new HashMap<>();
        hm.put(0,0);

        int sum = 0;
        // hm.put(0,-1);
        for( int  i = 0;i < nums.length; i++){
            int num = nums[i];
            sum+=num;

            if(hm.containsKey(sum%k)){
                if(hm.get(sum%k)  < i )
                    return true;
            }else
                hm.put(sum%k, i+1);

        }
        return false;
    }
}

class Solution {
    public int arithmeticTriplets(int[] nums, int diff) {

        int count=0;
        for(int i=0;i<nums.length;i++){
            for(int j=i+1;j<nums.length;j++){
                for(int k=j+1;k<nums.length;k++){
                    if(nums[j]-nums[i]==diff && nums[k] - nums[j] == diff){
                        count++;
                    }
                }
            }
        }

        return count;
    }
}

class Solution {
    public int[] rowAndMaximumOnes(int[][] mat) {
        int count;
