class Solution {
    public int tribonacci(int n) {
        if(n==0)return 0;
        if(n==1||n==2) return 1;
        int dp[]=new int[n+1];
        dp[0]=0;
        dp[1]=1;
        dp[2]=1;
        for(int i=3;i<=n;i++){
            dp[i]=dp[i-1]+dp[i-2]+dp[i-3];
        }
        return dp[n];
    }
}

class Solution {
    public int[] distinctDifferenceArray(int[] nums) {
        int n=nums.length;
        int ans[]=new int[n+1];

        for(int i=0;i<=n;i++){
            Set<Integer>set1=new HashSet<>();
            Set<Integer>set2=new HashSet<>();

            for(int j=0;j<=i;j++){
                set1.add(nums[j]);
            }
            for(int j=i+1;j<n;j++){
                set2.add(nums[j]);
            }

            ans[i]= set1.size() - set2.size();
        }
        return ans;
    }
}

