class Solution {
    public void nextPermutation(int[] n) {
        //breakpoint
       if(  n==null || n.length<=1)return;

		int i = n.length-2;

		while(i>=0 && n[i]>=n[i+1])i--;

		int j=n.length-1;

		if(i>=0) {
			while(n[j]<=n[i])j--;
			swap(n,i,j);
		}

		reverse(n,i+1,n.length-1);

		for(int p=0;p<n.length;p++) {
			System.out.println(n[p]);
		}

	}
	public static void swap(int n[],int i,int j) {
		int temp=n[i];
		n[i]=n[j];
		n[j]=temp;
	}
	public static void reverse(int n[],int i,int j) {
		while(i<j) {
			swap(n,i,j);
			i++;
			j--;
		}
	}
}

class Solution {
    public int findMaxFish(int[][] grid) {
        int sum=0;
        for(int i=0;i<=grid.length;i++)
        {
            for(int j=0;j<=grid[0].length;j++)
            {
                if(grid[i][j]!=0)
                {
                    int a[]=new int[1];
                    task(grid,i,j,a);
                    sum=Math.max(sum,a[0]);
                }
            }
        }
        return sum;
    }
    public void task(int grid[][], int i, int j, int a[])
    {
        if(i<0 || j<0 || i>=grid.length || j>=grid[0].length || grid[i][j]==0)
        {
            return;
        }
        a[0]+=grid[i][j];
        grid[i][j]=0;
        task(grid,i+1,j,a);
        task(grid,i-1,j,a);
        task(grid,i,j+1,a);
        task(grid,i,j-1,a);
    }
}

