class Solution {
    public int maxNumberOfBalloons(String text) {
        final int[][] cache = new int[2][5];
        cache[0][0] = 97;  // a
        cache[0][1] = 98;  // b
        cache[0][2] = 108; // l
        cache[0][3] = 110; // n
        cache[0][4] = 111; // o

        // cacl letter frequencies
        for (char ch : text.toCharArray()) {
            final int intValue = ch;
            for (int i = 0; i < 5; i++) {
                if (intValue == cache[0][i]) {
                    cache[1][i]++;
                    break;
                }
            }
        }

        // l & o meet twice
        cache[1][2] /= 2;
        cache[1][4] /= 2;

        // find the bottleneck
        int min = Integer.MAX_VALUE;
        for (int frequency: cache[1]) {
            min = Math.min(min, frequency);
        }

        return min;
    }
}

class Solution {
    private long maxStrength;

    public long maxStrength(int[] nums) {
        maxStrength = Integer.MIN_VALUE;
        helper(nums, 0, 1, 0);
        return maxStrength;
    }

    private void helper(int[] nums, int index, long product, int size) {
        if (index >= nums.length) {
            if(size != 0) maxStrength = Math.max(maxStrength, product);
            return;
        }

        helper(nums, index + 1, product * nums[index], size + 1);
        helper(nums, index + 1, product, size);
    }
}

class Solution {
    public int triangleNumber(int[] nums) {
        int n=nums.length;
        Arrays.sort(nums);
        int count=0;
        for(int c=n-1;c>=2;c--){
            int a=0;
            int b=c-1;
            while(a<b){
                if(nums[a]+nums[b]>nums[c]){
                    count+=(b-a);
                    b--;
                }
                else{
                    a++;
                }
            }
        }
        return count;

    }
}

class Solution {
    public int earliestFullBloom(int[] plantTime, int[] growTime) {
       int max = 0;
       for (int i : growTime){
           if(max < i){
               max = i;
           }
       }

       int len = max;
       int[] arr = new int[len + 1];
       int tmp = 0;
       int minTime = 0;

       for (int i = 0; i < plantTime.length; i++) {
           arr[growTime[i]] += plantTime[i];
       }

       for (int i = len; i > 0; i--) {
            if (arr[i] != 0) {
                tmp = tmp + arr[i];
                minTime = Math.max(minTime, tmp + i);
            }
       }

       return minTime;
    }
}

