class Solution {
    int [] dirs = {0, 1, 0, -1, 0};
    public int shortestPath(int[][] grid, int k) {
        int m = grid.length, n = grid[0].length;
        if(k = m+n -2) return m+n-2;

        boolean[][][] visited = new boolean [m][n][k+1];
        Queue<int[]> q = new LinkedList<>();
        q.offer(new int[]{0, 0, k, 0});
        visited[0][0][k] = true;

        while(!q.isEmpty()){
            int [] top = q.poll();

            int r = top[0], c = top[1], curk = top[2], dist = top[3];

            if(r == m-1 && c == n -1) return dist;
            for(int i = 0; i< 4; i++){
                int nr = r + dirs[i], nc = c + dirs[i + 1];
                if(nr < 0 || nr == m || nc < 0 || nc == n) continue;
                int newK = curk - grid[nr][nc];

                if(newK >= 0 && !visited[nr][nc][newK]){
                    visited[nr][nc][newK] = true;
                    q.offer(new int[]{nr, nc, newK, dist + 1});
                }
            }
        }
        return -1;
    }
}

class Solution {
    public String reverseWords(String s) {
        StringBuilder ans = new StringBuilder();
        for(int i=s.length()-1; i>=0; i--){
            if(s.charAt(i)==' '){
                continue;
            }
            int start=-1;
            for(int y=i-1; y>=0; y--){
                if(s.charAt(y)==' '){
                    start=y;
                    break;
                }
            }
            ans.append(s.substring(start+1, i+1) + " ");
            i=start;
        }
        ans.deleteCharAt(ans.length()-1);
        return ans.toString();
    }
}

class Solution {
    public int[][] transpose(int[][] matrix) {
        int[][] ans = new int[matrix[0].length][matrix.length];
        int row = 0;
        int col = 0;

        for(int i = 0; i < matrix.length; i++) {
            for(int j = 0; j < matrix[0].length; j++) {
                ans[row][col] = matrix[i][j];

                row++;

                if(row % ans.length == 0) {
                    row = 0;
                    col++;
                }
            }
        }
        return ans;
    }
}

