        if (sIndex = 100000)
            return -1;
        return sIndex;
    }
}

class Solution {
    private long[] dp;
    int MOD = (int)Math.pow(10 , 9) + 7;
    public long solve(int n){
        if(n==0) return 1;
        if(n<3) return n;

        if(dp[n]!=-1) return dp[n];

        return dp[n] = 2*solve(n-1)%MOD+solve(n-3)%MOD;
    }
    public int numTilings(int n) {
        this.dp = new long[n+1];
        Arrays.fill(dp , -1);

        return (int)solve(n)%MOD;
    }
}

class Solution {
    public int longestValidParentheses(String s) {
        Stack<Integer> st = new Stack<>();
        st.push(-1);
        int n = 0;
        for(int i = 0; i < s.length(); i++)
        {
            if(s.charAt(i) == '(')
                st.push(i);
            else if(s.charAt(i) == ')')
            {
                st.pop();
                if(st.empty())
                    st.push(i);
                else
                    n = Math.max(n, i - st.peek());
            }
        }
        return n;
    }
}

class Solution {
    int ans[];
    Map<Integer,List<Integer>> map=new HashMap<>();
    int temp[]=new int[0];
    int curr_node=0;
    List<Integer> vis=new ArrayList<Integer>();
    public int[] loudAndRich(int[][] richer, int[] quiet) {

        ans=new int[quiet.length];
        for(int i=0;i<=richer.length;i++){

            if(!map.containsKey(i)){
                map.put(i,new ArrayList());
            }
            if(i<richer.length && !map.containsKey(richer[i][0])){
                map.put(richer[i][0],new ArrayList());
                map.get(richer[i][0]).add(richer[i][1]);
            }
            else if(i<richer.length){
                map.get(richer[i][0]).add(richer[i][1]);
            }
        }

        Comparator<pair> comp=new Comparator<pair>(){
            public int compare(pair p1,pair p2){
                if(p1.cost == p2.cost){   
                    return 1;
                }
                else{
                    return -1;
                }

            }
        };
        PriorityQueue<pair> pq=new PriorityQueue<>(comp);
        for(int i=0;i<quiet.length;i++){
            ans[i]=-1;
            pq.add(new pair(i,quiet[i]));
        }

        while(!pq.isEmpty()){
            pair top=pq.poll();
            curr_node=top.node;
            if(!vis.contains(top.node)){
            dfs(top.node);
            }
        }
        return ans;

    }
    public void dfs(int node){
        if(ans[node]==-1){
            ans[node]=curr_node;
        }
        if(!vis.contains(node) && map.containsKey(node)){
            vis.add(node);

            for(int i : map.get(node)){
            dfs(i);

        }
        }

    }
}

