 *         this.val = val;
 *         this.left = left;
 *         this.right = right;
 *     }
 * }
 */
class Solution {
    public boolean isCompleteTree(TreeNode root) {
        boolean end = false;
        Queue<TreeNode> queue = new LinkedList<>();
        queue.offer(root);
        while(!queue.isEmpty()) {
            TreeNode currentNode = queue.poll();
            if(currentNode == null) {
                end = true;
            } else {
                if(end) {
                    return false;
                }
                queue.offer(currentNode.left);
                queue.offer(currentNode.right);
            }
        }
        return true;
    }
}

class Solution {
    double possible = 0.0;
    double valid = 0.0;

    public double getProbability(int[] balls) {
        int[] first = new int[balls.length];
        int[] second = new int[balls.length];
        dfs(balls, first, second, 0, 0, 0);
        return valid / possible;
    }

    private void dfs(int[] balls, int[] first, int[] second, int num1, int num2, int idx) {
        // finish all colors, check if this's a possible/valid distribution
        if (idx == balls.length) {
            // find one possible distribution
            if (num1 = num2) {
                // compute fake permutation
                double distrib = permFake(first) * permFake(second);
                possible += distrib;

                // find one valid distribution
                if (unique(first) == unique(second)) {
                    valid += distrib;
                }
            }
            return;
        }

        // distribute balls in current color to two bins
        for (int b = 0; b <= balls[idx]; b++) {
            first[idx] = b;
            second[idx] = balls[idx] - b;
            dfs (balls, first, second, num1 + first[idx], num2 + second[idx], idx + 1);
        }
    }

    // unique colors in 
    private int unique(int[] balls) {
        int unique = 0;
        for (int b: balls)
            unique += b > 0 ? 1 : 0;
        return unique;
    }

    // return 1 / (b1!b2!b3!...bn!) 
    private double permFake(int[] balls) {
        double ret = 1.0;
        for (int b: balls)
            ret /= factorial(b);
        return ret;
    }

    private int factorial(int n){
        int ret = 1;
        while (n > 0) {
            ret *= n;
            n--;
        }
        return ret;
    }
}

class Solution {
    public int max = 0;
    public int sum = 0;
    public int maxAreaOfIsland(int[][] grid) {
        for(int i = 0; i<grid.length;i++)
        {
            for(int j = 0; j<grid[i].length;j++)
            {
                if(grid[i][j]!=0)
                {
                    sum = 0; 
                    dfs(grid,i,j);
                    max  = Math.max(max,sum);
                }
            }
        }

        return max;
    }

    private void dfs(int[][] grid ,int r ,int c)
    {
        if(r>=grid.length || c>=grid[0].length || r<0|| c<0 || grid[r][c]==0)
        {
            return ;
        }

        sum++;
        grid[r][c] = 0;
        dfs(grid,r,c+1);
        dfs(grid,r,c-1);
        dfs(grid,r+1,c);
        dfs(grid,r-1,c);
    }
}

class Solution 
{
    public int trap(int[] height) 
    {
        int result = 0;
        if(height = null || height.length<=2)
            return result;
        int left[] = new int[height.length];
        int right[]= new int[height.length];
        //scan from left to right
        int max = height[0];
        left[0] = height[0];
        for(int i=1; i<height.length; i++)
        {
            if(height[i]<max)
            {
                left[i]=max;
            }
            else
            {
                left[i]=height[i];
                max = height[i];
            }
        }
        //scan from right to left
        max = height[height.length-1];
        right[height.length-1]=height[height.length-1];
        for(int i=height.length-2; i>=0; i--)
        {
            if(height[i]<max)
            {
                right[i]=max;  
            }
            else
            {  
                right[i]=height[i];
                max = height[i];
            }
        }

        for(int i=0; i<height.length; i++)
        {
            result+= Math.min(left[i],right[i])-height[i];
        }
        return result;
    }
}

