            for (int col = 0; col < n - 2; col++) {
                int temp = grid[row][col] + grid[row][col + 1] + grid[row][col + 2];
                temp += grid[row + 1][col + 1];
                temp += grid[row + 2][col] + grid[row + 2][col + 1] + grid[row + 2][col + 2];
