        ans=i=curRounds=curCustomers=rem=0
        while i<len(customers) or rem:
            if i<len(customers):
                rem+=customers[i]
                i+=1
            curRounds+=1
            if rem-4>=0:
                rem-=4
                curCustomers+=4
            else:
