class Solution:
def countAnagrams(self, s: str) -> int

    l = s.split()
    ans = 1

    for i in l:
        d = {}

        for j in i:
            if(d.get(j)):
                d[j] += 1
            else:
                d[j] = 1  

        duplicates = 1
        for j in d.values():
