class Solution:
    def cdist(self, it, distArray, distArrayIndex, edges):
        rdist = 0 
        nodes = []
        while it != -1 and distArray[it][distArrayIndex] > rdist:
            distArray[it][distArrayIndex] = rdist
            nodes.append(it)
            it = edges[it]
            rdist += 1
        return nodes

    def closestMeetingNode(self, edges: List[int], node1: int, node2: int) -> int:
        INF = float('inf')
        dist = defaultdict(lambda: [INF,INF])
        mmin, ans = INF, INF

        n = self.cdist(node1, dist, 0, edges)
        n += self.cdist(node2, dist, 1, edges)

        for k in n:
            m = max(dist[k])
            if m != INF:
                if m < mmin: 
                    mmin = m
                    ans = k
                elif m == mmin: 
                    ans = min(ans, k)

        return ans if ans != float('inf') else -1

class Solution:
    var dp = function(i,s,prev,k,ct,n,dct {
        if(k<0) {
            return Number.POSITIVE_INFINITY;
        }
        if(i>=n+1){
            x=0;
            if(ct>1){
                x=len(str(ct))+1;
            } elif(ct==1) {
                x=1;
            }
            return x;
        }
        if((i,prev,ct,k) in dct) {
            return dct[(i,prev,ct,k)];
        }
        if(s[i]==prev){
            inc=self.dp(i+1,s,prev,k,ct+1,n,dct);
        } else{
            x=0;
            if(ct>1){
                x=len(str(ct))+1;
            } elif(ct==1) {
                x=1;
            }
            inc=x+self.dp(i+1,s,s[i],k,1,n,dct);
        }
        exc=self.dp(i+1,s,prev,k-1,ct,n,dct);
        dct[(i,prev,ct,k)]=Math.min(inc,exc);
        return Math.min(inc,exc)
    }

