class Solution:
    def maxDistance(self, nums1: List[int], nums2: List[int]) -> int:
        def binary(left, right, num):
            farthestPos = 0
            while left < right:
                mid = (left + right) // 2
                if nums2[mid] < num:
                    right = mid
                else:
                    farthestPos = max(farthestPos, mid)
                    left = mid + 1
            if nums2[left] >= num:
                farthestPos = max(farthestPos, left)
            return farthestPos
        maxDiff = 0
        for i in range(min(len(nums1), len(nums2))):
            if nums1[i] > nums2[i]:
                continue
            else:
                j = binary(i, len(nums2)-1, nums1[i])
                maxDiff = max(maxDiff, (j-i))
        return maxDiff

class Solution:
    def findLHS(self, nums: List[int]) -> int:
        result = 0
        count_map = {}
        for num in nums:
            if num not in count_map:
                count_map[num] = 1
            else:
                count_map[num] += 1
        for num, count in count_map.items():
            if num + 1 in count_map:
                result = max(count + count_map[num + 1], result)
