class Solution:
    def isPossibleToCutPath(self, grid: List[List[int]]) -> bool:
        m, n = len(grid), len(grid[0])
        dirs = [(-1, 0), (0, -1)]
        def dfs(i: int, j: int) -> None:
            grid[i][j] = 2
            for di, dj in dirs:
                if 0 <= i + di < m and 0 <= j + dj < n and grid[i + di][j + dj] == 1: dfs(i + di, j + dj)

        dfs(m - 1, n - 1)

        dq = collections.deque([(0, 0)])
        grid[0][0] = 0
        dirs = [(1, 0), (0, 1)]
        while dq:
            l = len(dq)
            for _ in range(l):
                i, j = dq.popleft()
                if i == m - 1 and j == n - 1: return False
                for di, dj in dirs:
                    if 0 <= i + di < m and 0 <= j + dj < n and grid[i + di][j + dj] == 2: 
                        dq.append((i + di, j + dj))
                        grid[i + di][j + dj] = 0


            if len(dq) == 1 and dq[0] != (m - 1, n - 1): return True

        return True

from queue import Queue

class Solution:
    def frogPosition(self, n: int, edges: ArrayList[List[int]], t: int, target: int) -> float:
        if edges == []:
            if target == 1:return 1
            return 0

        d = {}
        for i in edges:
            d[i[0]] = d.get(i[0] , []) + [i[1]]
            d[i[1]] = d.get(i[1] , []) + [i[0]]

        visit = [0]*(n+1)

        q = Queue()     
        q.put([1 , 1])

        for dur in range(t+1):

            l = q.qsize()
            for i in range(l):
                temp = q.get()

                count = 0
                for ele in d[temp[0]]:
                    if visit[ele] == 0: count += 1

                if temp[0] == target and count == 0:     
                    return temp[1]

                if visit[temp[0]] != 0:    
                    continue

                visit[temp[0]] = 1

                for ele in d[temp[0]]:
                    if visit[ele] == 0: q.put([ele , temp[1]*(1/count)])


        l = q.qsize()
        for i in range(l):
            temp = q.get()
            if temp[0] == target:
                return temp[1]

        return 0

