class Solution:
    def isSubPath(self, head: Optional[ListNode], root: Optional[TreeNode]) -> bool:

        if head is None:
            return True

        if root is None:
            return False

        if head.val == root.val:
            if self.isSame(head, root):
                return True

        return self.isSubPath(head, root.left) or self.isSubPath(head, root.right)


    def isSame(self, head, root):

        if head is None:
            return True

        if root is None:
            return False

        if head.val = root.val: 
            return self.isSame(head.next, root.left) or self.isSame(head.next, root.right)

        return False

class Solution:
    def platesBetweenCandles(self, s: str, queries: List[List[int]]) -> List[int]:
        candies = [i for i, c in enumerate(s) if c == "|"]

        def bns(x: int) -> int:
            l, r = 0, len(candies) - 1
            while l <= r:
                m = (l + r) // 2
                if candies[m] < x: l = m + 1
                else: r = m - 1
            return l

        ans = []
        for a, b in queries:
            l, r = bns(a), bns(b + 1) - 1
            ans.append(candies[r] - candies[l] - (r - l) if l < r else 0)
        return ans

class Solution:
    def decodeCiphertext(self, encoded_text: str, rows: int) -> str:
        if rows == 1:
            return encoded_text

        N = len(encoded_text)
        cols = N // rows
        i, j, k = 0, 0, 0
        original_text = []

        while k < N:
            original_text.append(encoded_text[k])
            i += 1
            if i == rows:
                i = 0
                j += 1
            k = i*(cols + 1) + j

        return ''.join(original_text).rstrip()

mod = 10**9+7

class Solution:
    def countAnagrams(self, s: str) -> int:

        l = s.split()
        ans = 1

        for i in l:
            d = {}
        # counting frequencies of word i in dictionary d
            for j in i:
                if(d.get(j)):
                    d[j] += 1
                else:
                    d[j] = 1  

            duplicates = 1
            for j in d.values():
                duplicates *= math.factorial(j)
            curr = math.factorial(len(i))//duplicates

            ans *= curr
            ans = ans%mod

        return ans

class Solution:
    def numberOfArithmeticSlices(self, nums: List[int]) -> int:
        total, n = 0, len(nums)
        dp = [defaultdict(int) for _ in nums]
        for i in range(1, n):
            for j in range(i):
                diff = nums[j] - nums[i]
                dp[i][diff] += dp[j][diff] + 1
                total += dp[j][diff]
        return total

class Solution:
    def jump(self, nums: List[int]) -> int:
        L=len(nums)
        if L==1:
            return 0
        steps=[0]
        for i in range(nums[0]):
            steps.append(1)
        for index in range(1,L):
            len_steps=len(steps)
            if len_steps >= nums[index]+index+1:
                index += 1
            elif len_steps < nums[index]+index+1:
                for j in range(nums[index]+index-len_steps+1):
                    steps.append(steps[index+1]+1)
        return steps[L-1]

class Solution:
    def makeSmallestPalindrome(self, s: str) -> str:
        before = 0
        after = len(s)-1
        l = [i for i in s]
        while before <= len(s)/2:
            l[before] = min(l[before], l[after])
            l[after] = l[before]
            before+=1
            after-=1
        return "".join(l)

