        while start + 1 < end:
            mid = (start + end) // 2
            if self.check(stations, r, k, mid):
                start = mid
            else:
                end = mid
        if self.check(stations, r, k, end):
            return end
        else:
            return start

    def check(self, stations, r, k, target):
            n = len(stations)
            ans = True
            newStations = defaultdict(int)
            power = sum(stations[ : r])
            for i in range(n):
                if i + r < n:
                    power += stations[i + r]
                if i - r - 1 >= 0:
                    power -= stations[i - r - 1]
                if power >= target:
                    continue
                elif power + k < target:
                    ans = False
                    break
                else:
                    diff = target - power
                    power = target
                    stations[min(i + r, n - 1)] += diff
                    k -= diff
                    newStations[min(i + r, n - 1)] += diff
            for i in newStations:
                stations[i] -= newStations[i]
            return ans

class Solution:
    def sortString(self, s: str) -> str:
        freq = {}
        letters = sorted(set(s))
        res = ""
        for i in s:
            if i in freq:
                freq[i]+=1
            else:
                freq[i] = 1
        while freq:
            for i in letters:
                if  i in freq:
                    if freq[i]>0:
                        res+=i
                        freq[i]-=1
                    else:
                        del freq[i]

            for i in letters[::-1]:
                if  i in freq:
                    if freq[i]>0:
                        res+=i
                        freq[i]-=1
                    else:
                        del freq[i]


        return res

