class Solution:
    def dp(self,i,s,prev,k,ct,n,dct):
        if k<0:
            return float("infinity")
        if i>=n:
            x=0
            if ct>1:
                x=len(str(ct))+1
            elif ct==1:
                x=1
            return x
        if (i,prev,ct,k) in dct:
            return dct[(i,prev,ct,k)]
        if s[i]==prev:
            inc=self.dp(i+1,s,prev,k,ct+1,n,dct)
        else:
            x=0
            if ct>1:
                x=len(str(ct))+1
            elif ct==1:
                x=1
            inc=x+self.dp(i+1,s,s[i],k,1,n,dct)
        exc=self.dp(i+1,s,prev,k-1,ct,n,dct)
        dct[(i,prev,ct,k)]=min(inc,exc)
        return min(inc,exc)


    def getLengthOfOptimalCompression(self, s: str, k: int) -> int:
        n=len(s)
        return self.dp(0,s,"",k,0,n,{})

class Solution:
    def largestInteger(self, num: int) -> int:
        evenlist=[]
        oddlist=[]
        nums= [int(x) for x in str(num)]
        for i in nums:
            if i%2==0:
                evenlist.append(i)
            else:
                oddlist.append(i)
        even= [-x for x in evenlist]
        odd = [-x for x in oddlist]
        heapq.heapify(even)
        heapq.heapify(odd)
        result=[]
        for ele in nums:
            if ele in evenlist:
                result+=[-heapq.heappop(even)]
            if ele in oddlist:
                result+=[-heapq.heappop(odd)]
        result =[str(x) for x in result]                
        return int(''.join(result))

class Solution:
    def findSubstring(self, s: str, words: List[str]) -> List[int]:
        wlen= len(words[0])
        slen= wlen*len(words)
        track=dict()

        occ = collections.Counter(words)

        def test():
            for key, val in track.items():
                if val !=occ[key]:
                    return False
            return True
        res=[]
        #first look

        for k in range(wlen):
            for i in words:
                track.update({i : 0})
            for i in range(k,slen+k,wlen):
                w=s[i:i+wlen]
                if w in words:
                    track.update({w: track[w]+1})
            if test():
                res.append(k)
            #complete
            for i in range(wlen+k, len(s)-slen+1,wlen):

                nw=s[i+slen-wlen:i+slen]
                pw=s[i-wlen:i]
                if nw in words:
                    track.update({nw: track[nw]+1})
                if pw in words:
                    track.update({pw: track[pw]-1})
                if test():
                    res.append(i)
        return res

